INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_1 AS CHAR), 'SINGLE_CHOICE', '下列各句中，没有语病的一项是____', '["产业是会展的基础，会展是产业的舞台。杭州文博会不仅成为推动社会和经济效益“双丰收”的重要平台，更成为杭州文化的“秀场”搭建了世界各地多元文化交流的桥梁。", "专家表示，中国与东盟国家间紧密的贸易往来，对于推进区域可持续发展起着重要的作用。期待双方紧抓机遇，顺利推动2020年双向贸易额突破1万亿美元等愿景的实现。", "围棋作为文明交流的使者，五大洲越来越多的爱好者汇聚在一起。围棋蕴含着中华文明的智慧，为世界不同文明交流互鉴提供了生动的内容，它正以包容的姿态联接起世界。", "针对近期出现的游客乱扔垃圾、乱敲熔岩、乱涂乱画的不文明行为，双龙洞景区采取有效的办法，雇用了多名退休的阿姨做景区管理员，让她们阻止游客不文明行为的影响。"]', 'B', '参考答案：B。本题考查病句辨析，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列各句中，没有语病的一项是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_2 AS CHAR), 'SINGLE_CHOICE', '填入下文横线上的句子，与上下文衔接恰当的一项是____\n洞庭东山，两百年前还是太湖上的一座孤岛，____，西半部叫后山，峰岭峻峭。\n①岛的北端现在已和陆地相连\n②现在岛的北端已和陆地相连\n③全岛分成东西两个部分，一条鱼脊形成的山脉从北到南纵贯中央\n④一条鱼脊形成的山脉，从北到南，纵贯中央，把岛劈成东西两个部分\n⑤东半部称前山，坡势平缓\n⑥称为前山的东半部坡势平缓', '["①④⑤", "②③⑥", "①③⑥", "②④⑤"]', 'D', '参考答案：D。本题考查语言连贯与排序，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '填入下文横线上的句子，与上下文衔接恰当的一项是____\n洞庭东山，两百年前还是太湖上的一座孤岛，____，西半部叫后山，峰岭峻峭。\n①岛的北端现在已和陆地相连\n②现在岛的北端已和陆地相连\n③全岛分成东西两个部分，一条鱼脊形成的山脉从北到南纵贯中央\n④一条鱼脊形成的山脉，从北到南，纵贯中央，把岛劈成东西两个部分\n⑤东半部称前山，坡势平缓\n⑥称为前山的东半部坡势平缓');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_3 AS CHAR), 'SINGLE_CHOICE', '下列句子中标点符号的使用，正确的一项是____', '["不同的人，对“人是什么？”这个问题的回答是迥然不同的。即便是同一个人，不同时期也会有不同答案。", "“我这里并没有亲人。”“好歹叫他们送我回去。”“宝玉!宝玉!你好……”：黛玉在弥留之际的几句话值得我们细致分析。", "偏偏我来的不是时候，荔枝刚开花，满树浅黄色的小花，并不出众，新发的嫩叶，颜色浅红，比花还中看。", "北京奥运会闭幕式上飘逸的祥云纱在场内飞舞，缤纷的彩纸漫天飞扬，歌声，笑声，欢呼声响彻云宵，国家体育场成了欢乐的海洋。"]', 'B', '参考答案：B。本题考查标点符号，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列句子中标点符号的使用，正确的一项是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_4 AS CHAR), 'SINGLE_CHOICE', '下列各句中加下划线的成语使用恰当的一句是：____', '["某市原副市长许运鸿家教不严，其妻儿收受贿赂80多万元有人认为，许运鸿虽有不可推卸的责任，但因为他事先不知，所以$\\\\underline{罪不容诛}$。", "人们提到秋白同志，总会说起他是那样大公无私，光明磊落，$\\\\underline{求全责备}$自己。", "回首分手的时候，你我风华正茂，$\\\\underline{曾几何时}$，双鬓已染秋霜！", "五一期间，通往中华恐龙园的新区大道上人流如潮，$\\\\underline{接踵而至}$，形成一道假日旅游的亮丽风景线 。"]', 'C', '参考答案：C。本题考查词语成语运用，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列各句中加下划线的成语使用恰当的一句是：____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_9 AS CHAR), 'SINGLE_CHOICE', '从文后的选项中，选出最适合的一项作为该语段的结尾____\n被细雨浸润、滋养的苏堤苏醒了。新柳夹道，枝头舒展，一片鲜嫩的绿色。这可爱的年轻的垂柳，像妩媚倩巧的少女，温柔轻盈；____。', '["像垂披纷散秀发的古代美人，婆娑起舞；万般风流，像凌波微步的仙子", "婆娑起舞，像垂披纷散秀发的古代美人；万般风流，像凌波微步的仙子", "婆娑起舞，像垂披纷散秀发的古代美人；像凌波微步的仙子，万般风流", "像垂披纷散秀发的古代美人，婆娑起舞；像凌波微步的仙子，万般风流"]', 'D', '参考答案：D。本题考查语言基础综合，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '从文后的选项中，选出最适合的一项作为该语段的结尾____\n被细雨浸润、滋养的苏堤苏醒了。新柳夹道，枝头舒展，一片鲜嫩的绿色。这可爱的年轻的垂柳，像妩媚倩巧的少女，温柔轻盈；____。');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_1 AS CHAR), 'SINGLE_CHOICE', '下列各句中，没有语病的一句是____', '["为提升城市的知名度，加大城市的影响力，增强市民的自豪感，郑州正在全力打造中国“第八古都”。", "六年来，快报便民网以优质的服务、良好的信誉帮助南京百万家庭解决了生活中遇到的种种困难。", "在伊朗核问题上，中国能否和热爱和平的国家一道，阻止美军攻打伊拉克的悲剧重演，不仅符合中国的利益，也符合世界和谐发展的大势。", "日前，国家发改委等六部委联合发文，鼓励发展节能环保型小排量汽车，要求各地各部门在3月底前解除对小排量汽车的各种限制措施。"]', 'B', '参考答案：B。本题考查病句辨析，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列各句中，没有语病的一句是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_2 AS CHAR), 'SINGLE_CHOICE', '填入下文横线处的句子，与文意最连贯的一项是____\n任何一个神经细胞的兴奋，都会引起一系列与之有关的记忆群的活动。情节是以“自我”来根据事物内容自问自答，边设置场景、角色，边加以深化发展的。形象思维构出画面(可视内容)，语言记忆(逻辑思维)则是“自我”根据画面内容做出的逻辑反应，成为下一个画面的心理要求，概括地说，____。', '["逻辑思维内容确定了形象思维内容，形象思维又诱导了逻辑思维", "逻辑思维内容确定了形象思维内容，同时又诱导了形象思维", "形象思维内容确定了逻辑思维内容，同时又诱导了逻辑思维", "形象思维内容确定了逻辑思维内容，逻辑思维又诱导了形象思维"]', 'D', '参考答案：D。本题考查语言连贯与排序，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '填入下文横线处的句子，与文意最连贯的一项是____\n任何一个神经细胞的兴奋，都会引起一系列与之有关的记忆群的活动。情节是以“自我”来根据事物内容自问自答，边设置场景、角色，边加以深化发展的。形象思维构出画面(可视内容)，语言记忆(逻辑思维)则是“自我”根据画面内容做出的逻辑反应，成为下一个画面的心理要求，概括地说，____。');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_3 AS CHAR), 'SINGLE_CHOICE', '下列各项中，标点符号的使用合乎规范的一项____', '["牛肉为何不是那个味?近来，工商部门调查发现，热销的“张飞牛肉”原是将牛肉打碎、重新粘合、压制，“注射”植物蛋白并加人了添加剂的“打针”重组牛肉。", "于是，人与兽的根本不同就在于，人可以用精神疗救肉体；也可以用精神的记述——书籍，拓展延续生命的疆域，使生命不朽。", "黄鹤楼前迎“祥云”，三峡坝上传火炬，荆州古城展“楚韵”……5月29日，北京奥运圣火“祥云”抵达湖北，在荆楚大地展开了为期三天的传递。", "火星上有水，终于有了直接的“目击证据”。科学家近日证实，美国宇航局“凤凰”号探测器在火星极地发现了水冰（探测器发回的两张照片清晰地留下了火星存在水冰的直接证据。）"]', 'C', '参考答案：C。本题考查标点符号，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列各项中，标点符号的使用合乎规范的一项____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_4 AS CHAR), 'SINGLE_CHOICE', '下列词语中注音全都正确的一项是____', '["感喟(ｋｕì)     素昧平生(ｍèｉ)     信手拈来(ｚｈāｎ)", "喝彩(ｈè)       自怨自艾(ｙì)       力能扛鼎（ｋàｎɡ）", "眼睑(ｊｉǎｎ)   戛然而止(ｊｉá)      刚愎自用(ｂì)", "关卡(ｑｉǎ)     越俎代庖(ｂāｏ)      闻者咋舌（ｚé）"]', 'C', '参考答案：C。本题考查词语成语运用，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列词语中注音全都正确的一项是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_9 AS CHAR), 'SINGLE_CHOICE', '下列括号中的两种表述全都正确的一组是____\n拉登这个世界头号恐怖主义分子，身穿金丝镶边的阿拉伯长袍，头扎红白相间的格子头巾，（①长着满脸大胡子②脸上长满大胡子），眼睛略带忧郁，性格腼腆，言辞温和太行山猕猴保护区，（③不论高山、深谷，不论草原、湖泊，不论森林、溪流④不论高山、深谷，不论草原、森林，不论溪流、湖泊），处处都有随意生长的奇花异草，处处都有悦耳的鸟鸣。', '["①③", "①④", "②③", "②④"]', 'D', '参考答案：D。本题考查语言基础综合，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列括号中的两种表述全都正确的一组是____\n拉登这个世界头号恐怖主义分子，身穿金丝镶边的阿拉伯长袍，头扎红白相间的格子头巾，（①长着满脸大胡子②脸上长满大胡子），眼睛略带忧郁，性格腼腆，言辞温和太行山猕猴保护区，（③不论高山、深谷，不论草原、湖泊，不论森林、溪流④不论高山、深谷，不论草原、森林，不论溪流、湖泊），处处都有随意生长的奇花异草，处处都有悦耳的鸟鸣。');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_1 AS CHAR), 'SINGLE_CHOICE', '下列各句中没有语病的一句是____', '["有效解决看病贵、看病难的问题是当今中国的一个紧迫课题，它不仅关系到我们能否继续坚持“以人为本”的导向，而且影响到我们能否继续推进社会主义事业的长远大计。", "抗生素曾经是人类健康的福音，但是如果使用不合理，下药不对症，即使它是灵丹妙药，最终它给患者带来的也只能是可能超过疾病本身的伤害。", "伊朗最近进行大规模军事演习并且接连成功试射新型导弹令美国军方十分震惊，但真正令五角大楼担心的是伊朗已经研制出能够携带核弹头的导弹。", "新闻媒体报道的西安市蓝田县某乡村教师借钱搭车数十里，将捡到的4000元现金送还失主在三秦大地引起强烈反响。"]', 'C', '参考答案：C。本题考查病句辨析，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列各句中没有语病的一句是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_2 AS CHAR), 'SINGLE_CHOICE', '依次填入下面文中横线处的语句，与上下文衔接最恰当的一组是____\n读书原为自己受用，多读不能算是荣誉，少读也不能算是羞耻。____，必能养成深思熟虑的习惯，以至于变化气质；____，譬如漫游“十里洋场”，虽珍奇满目，徒惹得眼花缭乱，空手而归。____，如暴发户炫耀家产，以多为贵。这在治学方面是自欺欺人，在做人方面是趣味低劣。\n①多读如果彻底\n②少读如果彻底\n③多读而不求甚解\n④少读而不求甚解\n⑤世间许多人读书只为装点门面\n⑥世间许多读书人只为装点门面', '["②③⑤", "①③⑥", "②④⑤", "①④⑥"]', 'A', '参考答案：A。本题考查语言连贯与排序，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '依次填入下面文中横线处的语句，与上下文衔接最恰当的一组是____\n读书原为自己受用，多读不能算是荣誉，少读也不能算是羞耻。____，必能养成深思熟虑的习惯，以至于变化气质；____，譬如漫游“十里洋场”，虽珍奇满目，徒惹得眼花缭乱，空手而归。____，如暴发户炫耀家产，以多为贵。这在治学方面是自欺欺人，在做人方面是趣味低劣。\n①多读如果彻底\n②少读如果彻底\n③多读而不求甚解\n④少读而不求甚解\n⑤世间许多人读书只为装点门面\n⑥世间许多读书人只为装点门面');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_3 AS CHAR), 'SINGLE_CHOICE', '下列各句中，标点符号使用正确的一句是____', '["你可曾想到白发苍苍的老父老母?可曾想到嗷嗷待哺的儿女?可曾想到孩子们稚嫩的心灵?将因此而蒙受巨大的创伤!", "这组策划报道正处于植树季节,时效性强,“用数据说话”,不仅具有说服力,更具有号召力——号召市民投身到护绿建绿的队伍中来!", "要有意思才有话说；没有意思硬要说，就是瞎说；意思没有想清楚随便说，就是乱说；那都是没有把话说好。", "小雨突发奇想地说：“今天阳光灿烂，我上你家看看好吗？”博文打趣地说：“去我家？去我家干嘛，扶贫吗，哈哈。”"]', 'B', '参考答案：B。本题考查标点符号，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列各句中，标点符号使用正确的一句是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_4 AS CHAR), 'SINGLE_CHOICE', '下列词语注音全都错误的一组是____', '["谲（jué）诈\\t缱绻（quǎn）\\t嗥（háo）叫\\t妍（yán）媸毕露", "糟粕（pò）\\t舛（chuǎn）误\\t巷（xiàng）道\\t潜（qián）移默化", "档（dǎng）次\\t鲫（jí）鱼\\t与（yǔ）会\\t缉（jí）拿归案", "僭（zān）称\\t口讷（nè）\\t郝（nǎn）然\\t同仇敌忾（gài）"]', 'C', '参考答案：C。本题考查词语成语运用，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列词语注音全都错误的一组是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_9 AS CHAR), 'SINGLE_CHOICE', '下文括号中的两种表述全都正确的一项是____\n北部湾有一处绵延20多公里的银色沙滩，它的特点是：（①水温和，浪柔软；滩平长，沙细白②滩平长，沙细白；水温和，浪柔软），无鲨鱼，无污染。白天徜徉在沙滩，（③海风吹来，涛声阵阵；归帆点点，鸥鸟振翅④归帆点点，鸥鸟振翅；海风吹来，涛声阵阵），令人浑然忘我。', '["②③", "②④", "①③", "①④"]', 'A', '参考答案：A。本题考查语言基础综合，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下文括号中的两种表述全都正确的一项是____\n北部湾有一处绵延20多公里的银色沙滩，它的特点是：（①水温和，浪柔软；滩平长，沙细白②滩平长，沙细白；水温和，浪柔软），无鲨鱼，无污染。白天徜徉在沙滩，（③海风吹来，涛声阵阵；归帆点点，鸥鸟振翅④归帆点点，鸥鸟振翅；海风吹来，涛声阵阵），令人浑然忘我。');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_1 AS CHAR), 'SINGLE_CHOICE', '下列各句没有语病的一句是____', '["光纤宽带的普及，不仅方便了普通大众生活，还为小微企业降低网络成本和稳固的高速网络基础，激发了社会创业创新热情，为经济发展提供了新动能。", "经过两天的紧张工作，长征七号运载火箭所有部件16日下午安全运抵海南文昌航天发射场。我国新建成的航天发射场发射任务首次进入全面实施阶段。", "敦煌研究院通过官方微信首次披露了一批涉及古代敦煌端午节民俗壁画及古文献，端午民俗不仅活动丰富，且有文人雅趣伴随其中，十分优雅浪漫。", "香港科学园区是香港高新科技以及应用科技的一个研发基地，从2001年开始启用，目前分为三期一共有600多家企业进驻，主要以创新科技企业为主。"]', 'C', '参考答案：C。本题考查病句辨析，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列各句没有语病的一句是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_2 AS CHAR), 'SINGLE_CHOICE', '与下文衔接最恰当的一项是____\n贪污2500万，挪用200万元的国际航空公司财务处副科长杨宁钻到地下室，偷偷躲了起来，____，从地下室拽了出来，送到了该去的地方。', '["公安人员找了好久，最后才发现他", "但后来还是让公安人员给找到了", "使公安人员找了好久，终于把他找到", "但公安人员毕竟发现了他"]', 'B', '参考答案：B。本题考查语言连贯与排序，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '与下文衔接最恰当的一项是____\n贪污2500万，挪用200万元的国际航空公司财务处副科长杨宁钻到地下室，偷偷躲了起来，____，从地下室拽了出来，送到了该去的地方。');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_3 AS CHAR), 'SINGLE_CHOICE', '下列各句中标点符号使用错误的一项是____', '["建筑的新奇美观与节能环保并不是“鱼和熊掌不可兼得”，关键是在项目设计方案阶段，就要像重视建筑外观设计一样，是否重视建筑的生态和节能设计。", "中美分别是最大的发展中国家和最大的发达国家，两国发展建设性合作关系不仅符合当今世界求和平、谋发展、促合作的时代潮流，也符合两国的根本利益。", "“百家讲坛”是个成功的舞台，走上它的每一个人都有了自己的辉煌。从易中天开始，到现在，则轮到了一位女性（于丹），这个再次以《论语》系列创下“百家讲坛”收视高峰的北师大教授。", "据统计，多哈亚运会大约90%的专卖产品来自中国，“中国元素”已经成为本届亚运会的一道亮丽风景。"]', 'C', '参考答案：C。本题考查标点符号，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列各句中标点符号使用错误的一项是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_4 AS CHAR), 'SINGLE_CHOICE', '下面两个划线处依次填人的最恰当的语句是____\n广播通讯社为了迅速提高通讯员的写作水平，____新闻写作知识讲话，____送到每个通讯员手中，供他们学习参考。', '["在本刊连续刊载 然后这些刊物被及时", "由本刊连续刊载 于是这些刊物被及时", "于本刊连续刊载 接着把这些刊物及时", "让本刊连续刊载 并且把这些刊物及时"]', 'D', '参考答案：D。本题考查词语成语运用，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下面两个划线处依次填人的最恰当的语句是____\n广播通讯社为了迅速提高通讯员的写作水平，____新闻写作知识讲话，____送到每个通讯员手中，供他们学习参考。');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_9 AS CHAR), 'SINGLE_CHOICE', '下列新闻标题中，语意明确的一句是____', '["政府有关部门明令禁止取缔药品交易市场", "真正优秀的教师无一不是道德修养的模范", "独联体国家看不上2002年世界杯足球赛", "警方对报案人称围观者坐视不管表示愤恨"]', 'B', '参考答案：B。本题考查语言基础综合，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列新闻标题中，语意明确的一句是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_1 AS CHAR), 'SINGLE_CHOICE', '下列各句中，有语病的一句是____', '["青年作家残雪认为鲁迅的作品实现了一种“突破”，而《故事新编》中的《铸剑》则将这种创造登峰造极。", "“要透过现象看本质”，这样的要求，没有开阔的视野和一定的辩证思维能力，是不可能达到的。", "这种蝴蝶和候鸟一样，冬天都飞往南方，夏天又飞向北方，平均每天飞行约四十公里。", "我们有些影视导演热衷于费精力仿造什么“古”街，结果却是现代化的，或是俗不可耐的，这样劳心费力又是何苦？"]', 'D', '参考答案：D。本题考查病句辨析，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列各句中，有语病的一句是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_2 AS CHAR), 'SINGLE_CHOICE', '下面是中美联合公报上的一句话，填人横线上的句子正确的是____\n美国方面认识到，台湾海峡两边的中国人都认为，只有一个中国，____。', '["台湾是中国的一个省", "台湾是中国的一部分", "台湾是中国不可分割的一部分", "台湾自古以来就是中国不可分割的一部分"]', 'B', '参考答案：B。本题考查语言连贯与排序，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下面是中美联合公报上的一句话，填人横线上的句子正确的是____\n美国方面认识到，台湾海峡两边的中国人都认为，只有一个中国，____。');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_3 AS CHAR), 'SINGLE_CHOICE', '标点符号使用正确的一项是____', '["“吾生也有涯，而知也无涯”一语，出自《庄子一养生主》。", "鲁迅《记念刘和珍君》一文中“亲戚或余悲，他人亦已歌。死去保所道，托体同山阿”四句诗，引自陶渊明所作的《挽歌》。", "一九三三年至一九三四年之间，鲁迅先生经常在《申报副刊》《自由谈》上写稿，攻击时弊。", "前夜看了“塞上风云”的预告片，便又回忆起猩猩峡外的沙漠来了。"]', 'B', '参考答案：B。本题考查标点符号，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '标点符号使用正确的一项是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_4 AS CHAR), 'SINGLE_CHOICE', '下列词语中下划线的读音，全都相同的一组是____', '["$讥\\\\underline{诮}$  $蹊\\\\underline{跷}$ $ 金蝉脱\\\\underline{壳}$ $山势\\\\underline{峭}拔$", "$\\\\underline{熄}火$ $\\\\underline{檄}文$ $\\\\underline{嬉}皮笑脸$ $\\\\underline{息}事宁人$", "$\\\\underline{戍}守$ $\\\\underline{庶}民$ $\\\\underline{数}典忘祖$ $\\\\underline{束}手待毙$", "$\\\\underline{档}案$ $\\\\underline{当}成$ $碧波\\\\underline{荡}漾$ $跌\\\\underline{宕}起伏$"]', 'D', '参考答案：D。本题考查词语成语运用，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列词语中下划线的读音，全都相同的一组是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_9 AS CHAR), 'SINGLE_CHOICE', '下列字注音全对的一项是	____', '["前仆（pū）后继   潸（shān）然泪下 荫（yìn）庇   青冢（zhǒng）", "衣（yī）锦还乡   针砭（biǎn）时弊    埋（mán）怨\\t绵亘（gèng）", "人心叵（pǒ）测   箪食（sì）壶浆      慰藉（jì）\\t投奔（bèn）", "爱憎（zēng）分明、淆（xíao）乱乾坤   梦魇（yǎn）\\t熨（yùn）帖"]', 'A', '参考答案：A。本题考查语言基础综合，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列字注音全对的一项是	____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_1 AS CHAR), 'SINGLE_CHOICE', '下列病句中，没有语病的一项是____', '["毋庸置疑，杜牧是唐诗史甚至是中国文学史上值得铭记的人物。但无论是唐诗的故乡，还是杜牧的家乡，都没有一处正规的、完善的纪念景点。", "经济发展与文物保护之间的矛盾愈发凸显，典型的一个问题是土地资源的矛盾，城市化的发展进一步加剧了这种矛盾。在发展的过程中，文物保护的紧迫性也逐渐认识。", "国务院发布《关于加强文化遗产保护的通知》，这则通知体现了“文物”相对“文化遗产”来说，其内涵和外延的扩大和提升，同时强调了保护文化遗产的重要性和紧迫性。", "名人墓保护刻不容缓，一方面政府应加快相关法律法规的完善和运行，另一方面还要落实保护资金，此外，全社会也应增强保护意识。"]', 'A', '参考答案：A。本题考查病句辨析，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列病句中，没有语病的一项是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_2 AS CHAR), 'SINGLE_CHOICE', '填入下文横线处正确的一项是____\n____，《邹忌讽齐王纳谏》、《召公谏厉王止谤》这两篇古文，我们对照着读，大有可以借鉴之处。', '["谏难，纳谏尤难", "追古思今", "历史是一面镜子", "事因难能，所以可贵"]', 'A', '参考答案：A。本题考查语言连贯与排序，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '填入下文横线处正确的一项是____\n____，《邹忌讽齐王纳谏》、《召公谏厉王止谤》这两篇古文，我们对照着读，大有可以借鉴之处。');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_3 AS CHAR), 'SINGLE_CHOICE', '下列标点符号使用不正确的一项是____', '["文天祥在缧绁之中，是常拿了这几句诗勉励自己：“千年成败俱尘土，消得人间说丈夫”；“一死鸿毛或泰山，之轻之重安所处”！", "尼采说艺术世界的构成由于两种精神：一是“梦”，梦的境界是无数的形象（如雕刻）；一是“醉”，醉的境界是无比的豪情（如音乐）。", "四项协议顺利签署后，两岸大体上就能完成“三通”进程（通邮、通航、通商），这将为今后两岸关系更加全面发展提供必要的条件和基础。", "中国作协主席铁凝希望广大作家以更加自觉的姿态，坚持贴近实际、贴近生活、贴近群众，沉潜生活，冷静思考，与人民同心，与时代同行，创作出更多反映现实生活和人民主体地位、群众喜闻乐见的优秀作品。"]', 'C', '参考答案：C。本题考查标点符号，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列标点符号使用不正确的一项是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_4 AS CHAR), 'SINGLE_CHOICE', '下列词语的字音、字形有两个错误的一组是____', '["谙练（ān）　　麇集（qún）　　巨擘（bò）　　幡然悔悟（fān）", "拱券（xuàn）　罹难（lí）　　 抵毁（dǐ） 　　提纲絜领（qiè）", "踅摸（xué）　 纰缪（pī）　　昡晕（xuàn） 　分道扬镳（biāo）", "翩跹（qiān）　庾毙（yǔ）　　 香蕈（xùn） 　 循私舞弊（xùn）"]', 'B', '参考答案：B。本题考查词语成语运用，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列词语的字音、字形有两个错误的一组是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_9 AS CHAR), 'SINGLE_CHOICE', '下列语句表述无误的一项是____', '["3月27日，北京迎来了入春以来第四个沙尘天气。这次沙尘天气是蒙古国东南部和中国内蒙古、甘肃、宁夏等地区大规模爆发沙尘暴。", "为全面建设小康社会，全党全社会要共同关心和支持安全生产工作，形成齐抓共管的最大合力，创造更加良好的社会环境，加快社会主义现代化建设的步伐。", "3月6日至4月30日，上海神诺富特大酒店二层甲板咖啡厅特邀来自国籍为泰国、马来西亚、新加坡的大厨们为爱好美食的您精心演绎东南亚美食精髓，带给您全新的美食体验。", "湖南师范大学社会学教授陈成文指出，“杀人”游戏属于心理暗示游戏，从中追求游戏的快感和刺激程度往往容易沉迷其中，这对培养一个健康的心态是非常不利的。"]', 'B', '参考答案：B。本题考查语言基础综合，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列语句表述无误的一项是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_1 AS CHAR), 'SINGLE_CHOICE', '下列句子没有语病的一项是____', '["踩踏致死事故是可怕的，但也是可防可控的，虽然说到底，这是“人”的问题。", "总部位于瑞典的全球挑战基金会7月10日公布了一项调查报告显示，大多数人认为，目前世界比两年前更加危险。", "有调研显示，因睡眠不足导致的生产力下降、道路事故、工伤与猝死等所造成的直接经济损失高达数十亿美元。", "美国海军近日公布女兵发型新标准——允许女兵绑马尾辫或梳其他发型，这打破了之前女兵发型的烦琐而死板的规定。"]', 'D', '参考答案：D。本题考查病句辨析，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列句子没有语病的一项是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_2 AS CHAR), 'SINGLE_CHOICE', '填入下文划线处恰切的一项是____\n自从我们搬到郊外以来，____。那短篱边牵延着的毛豆叶子，已露出枯黄的颜色来，白色的小野菊，一丛丛由草堆里攒出头来，还有小朵的黄花在凉劲的秋风中抖颤，这一景象，最易勾起人们的秋思，况且身在阿富汗呢?', '["天气逐渐清凉了", "异国秋色愈来愈浓了", "秋风日渐凄冷了", "秋天的脚步愈来愈近了"]', 'A', '参考答案：A。本题考查语言连贯与排序，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '填入下文划线处恰切的一项是____\n自从我们搬到郊外以来，____。那短篱边牵延着的毛豆叶子，已露出枯黄的颜色来，白色的小野菊，一丛丛由草堆里攒出头来，还有小朵的黄花在凉劲的秋风中抖颤，这一景象，最易勾起人们的秋思，况且身在阿富汗呢?');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_3 AS CHAR), 'SINGLE_CHOICE', '下列各句中，标点符号使用不正确的一项是____', '["鲁迅作品（如《孔已己》《药》《祝福》《示众》等）中有大量写“看客”的文字，旨在批判国民劣根性。", "不料这秃儿却拿着一支黄漆的棍子——就是阿Q所谓的哭丧棒——大踏步走了过来。", "鲁迅晚年还完成了一部小说集《故事新编》（1936年出版）。", "请同学们给下面的诗句划分节奏，朗读几遍，说说它们对本诗的风格起什么作用？"]', 'D', '参考答案：D。本题考查标点符号，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列各句中，标点符号使用不正确的一项是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_4 AS CHAR), 'SINGLE_CHOICE', '依次为下列两副对联选填的词语，正确的一项是____\n1936年鲁迅先生逝世时，美国作家斯诺撰写了一副挽联，托人送到鲁迅先生追悼会上。挽联是：译著尚未成书，惊闻陨星，____何人领呐喊?先生____作古，痛忆旧雨，文坛从此感彷徨！\n1990年德高望重的徐向前元帅逝世，越共领导人黄文欢即书一联以悼之，挽联是：____军心暖，威震沙场敌胆寒。', '["寰宇 已经 同甘共苦", "中国 不幸 同甘共苦", "中国 已经 身先士卒", "寰宇 不幸 身先士卒"]', 'C', '参考答案：C。本题考查词语成语运用，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '依次为下列两副对联选填的词语，正确的一项是____\n1936年鲁迅先生逝世时，美国作家斯诺撰写了一副挽联，托人送到鲁迅先生追悼会上。挽联是：译著尚未成书，惊闻陨星，____何人领呐喊?先生____作古，痛忆旧雨，文坛从此感彷徨！\n1990年德高望重的徐向前元帅逝世，越共领导人黄文欢即书一联以悼之，挽联是：____军心暖，威震沙场敌胆寒。');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_9 AS CHAR), 'SINGLE_CHOICE', '下列各句中，语意明确的一句是____', '["印度洋海啸发生后，中国政府进行了迄今为止最大规模的对外救援行动。", "今天老师又在班会上表扬了自己，但是我觉得还需要继续努力。", "祁爱群看见组织部新来的援藏干部很高兴，于是两人亲切地交谈起来。", "因患病住院，83岁高龄的黄昆和正在美国的姚明没能到场领奖。"]', 'A', '参考答案：A。本题考查语言基础综合，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列各句中，语意明确的一句是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_1 AS CHAR), 'SINGLE_CHOICE', '下列没有语病的一句是____', '["会议对“十一五”规划纲要草案提出了“十一五”时期我国经济社会发展的重大改革措施和主要政策取向的讨论是很富有成效的。", "在现代市场中，知识产权保护、品牌策划、市场营销、客户服务等形成了环环相扣的产业化“长链”，任何一环失误，都可能导致企业在市场上的失败。", "世界卫生组织的调查指出，目前人类80%的疾病是饮水不良引起的，全球有近20亿人由于饮用受污染的水而遭受疾病。", "本次冬奥会闭幕式打破了以往按照国家入场的习俗，而是各国旗手举着国旗一同入场，中国代表团的旗手是韩晓鹏。お"]', 'B', '参考答案：B。本题考查病句辨析，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列没有语病的一句是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_2 AS CHAR), 'SINGLE_CHOICE', '填入下文横线上的话，与上下文衔接最好的一项是____\n有人说战争没什么好写，因为战争是丑的，是破坏的。假如社会上的一切都可以作为文艺作品的材料，不知为何单单把战争排除在外；假如文艺含有奖善惩恶的目的，那么，____，为什么不可以写呢?', '["写战争就是写善与恶的交锋", "战争正是善与恶的交锋", "战争正是善与恶交锋的材料", "写战争用的就是善与恶交锋的材料"]', 'B', '参考答案：B。本题考查语言连贯与排序，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '填入下文横线上的话，与上下文衔接最好的一项是____\n有人说战争没什么好写，因为战争是丑的，是破坏的。假如社会上的一切都可以作为文艺作品的材料，不知为何单单把战争排除在外；假如文艺含有奖善惩恶的目的，那么，____，为什么不可以写呢?');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_3 AS CHAR), 'SINGLE_CHOICE', '下列标点符号使用正确的一项是____', '["“对于我，我的这本书是这样的，”王强说：“军训，已经成为一种宝贵的难得的一种经历和力量，支撑着自己在人生旅途的各种风雨中保持心灵的坚韧，而军训给我最美好的记忆，是同学们和教官之间纯洁淳朴充满人情味的关怀鼓励和相互扶持。”", "9月20日15时15分，神七载人飞船、长征二号Ｆ运载火箭和逃逸塔组合体，顺利垂直转运至发射区，标志着神七任务已进入最后的发射、准备阶段。", "医疗机构要购置必要的医疗检查设备，规范诊疗方案、标准和信息报告制度，加强流行病学调查，开展对有问题奶制品的健康危害评估，组织有关专家向公众介绍有关医学知识。", "三聚氰胺是何鬼怪妖孽，怎么会引起人们这么大的恐慌？原来，由于生产出来的奶粉中蛋白质含量不“达标”，三聚氰胺就开始被不法商人作起了食品添加剂，以提升食品检测中的蛋白质含量指标。"]', 'C', '参考答案：C。本题考查标点符号，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列标点符号使用正确的一项是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_9 AS CHAR), 'SINGLE_CHOICE', '下文括号中的两种表述全部正确的一项是____\n转过插屏，小小的三间厅，厅后就是后面的正房大院。（①正面五间上房，皆雕梁画栋，两边穿山游廊厢房，挂着各色鹦鹉、画眉等鸟雀②两边穿山游廊厢房，挂着各色鹦鹉、画眉等鸟雀，正面五间上房，皆雕梁画栋），台矶之上，坐着几个穿红着绿的丫头。\n伊豆山已经衔住落日，（③夕阳从容不迫地一寸又一寸，一分又一分，顾盼着行将离别的世界。太阳落一分，浮在海面上的霞光就后退八里④太阳落一分，浮在海面上的霞光就后退八里。夕阳从容不迫地一寸又一寸，一分又一分，顾盼着行将离别的世界），悠悠然沉落下去。', '["①④", "①③", "②④", "②③"]', 'A', '参考答案：A。本题考查语言基础综合，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下文括号中的两种表述全部正确的一项是____\n转过插屏，小小的三间厅，厅后就是后面的正房大院。（①正面五间上房，皆雕梁画栋，两边穿山游廊厢房，挂着各色鹦鹉、画眉等鸟雀②两边穿山游廊厢房，挂着各色鹦鹉、画眉等鸟雀，正面五间上房，皆雕梁画栋），台矶之上，坐着几个穿红着绿的丫头。\n伊豆山已经衔住落日，（③夕阳从容不迫地一寸又一寸，一分又一分，顾盼着行将离别的世界。太阳落一分，浮在海面上的霞光就后退八里④太阳落一分，浮在海面上的霞光就后退八里。夕阳从容不迫地一寸又一寸，一分又一分，顾盼着行将离别的世界），悠悠然沉落下去。');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_1 AS CHAR), 'SINGLE_CHOICE', '下列没有语病的一项是____', '["“人类安全”对APEC会议是一个全新的概念，涉及反恐、自然灾害、疾病、能源安全等领域，与会者将把它作为最重要的议题之一进行积极的沟通和讨论。", "根据对春节期间家禽消费量可能增加、长途运输比较频繁的预测，有关部门希望逐步推广集中屠宰和白条鸡上市，以减少活禽对人的感染机会。", "希望工程的意义不仅在于建造多少所漂亮学校，资助多少个失学孩子，还在于为中国社会公益事业的起步和发展起到了示范作用。", "“十一五”时期，本市将以建设都市农业为主题增强农业综合功能，重点发展农村公共事业，力求提高农民的生活质量，促进新农村的建设步伐。"]', 'C', '参考答案：C。本题考查病句辨析，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列没有语病的一项是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_2 AS CHAR), 'SINGLE_CHOICE', '填到空缺处与上下文衔接较好的一项是____\n列宁说：“语言是人类最重要的交际工具。”这一科学论断深刻地阐明了语言的社会本质和重要作用。人们利用语言来进行交际，交流思想，____，如果没有语言，社会便会停止生产，便会崩溃。', '["以便协调共同的活动，互相了解，组织社会的生产", "以便协调共同的活动，组织社会的生产，互相了解", "以便互相了解，协调共同的活动，组织社会的生产", "以便互相了解，组织社会的生产，协调共同的活动"]', 'C', '参考答案：C。本题考查语言连贯与排序，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '填到空缺处与上下文衔接较好的一项是____\n列宁说：“语言是人类最重要的交际工具。”这一科学论断深刻地阐明了语言的社会本质和重要作用。人们利用语言来进行交际，交流思想，____，如果没有语言，社会便会停止生产，便会崩溃。');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_3 AS CHAR), 'SINGLE_CHOICE', '下列句子中，标点符号使用正确的一句是____', '["“夺冠不是一件容易的事，”姚明苦笑了一下说：“人们往往只看到了鲜花和掌声，而忽视这背后的汗水和辛苦呀!”", "毛泽东有两句诗：“独有英雄驱虎豹，更无豪杰怕熊罴”，我从中感受到了共产党人的大无畏精神。", "假如有这样一本书，能给“下海”或将要“下海”者以警示，告诉他们何处可能有陷阱，怎样才能达到金光灿烂的彼岸，那该多好!", "东家说：“我家地里杏树上有一窝斑斑，(斑斑，方言，即斑鸠)你看那树上斑斑乱飞，怕是有孩子在摘杏儿呢。”"]', 'C', '参考答案：C。本题考查标点符号，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列句子中，标点符号使用正确的一句是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_9 AS CHAR), 'SINGLE_CHOICE', '下文划线处选填哪项才恰当____\n春意甚浓了，但在北方还是五风十雨，春寒料峭，____，又来了一场沁人心脾的冷雨。', '["刚吹过一阵暖人心意的春风", "一阵乌云刚刚布满天空", "刚飞过一群欢叫的大雁", "一堆堆令人生寒的积雪还依稀可见"]', 'A', '参考答案：A。本题考查语言基础综合，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下文划线处选填哪项才恰当____\n春意甚浓了，但在北方还是五风十雨，春寒料峭，____，又来了一场沁人心脾的冷雨。');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_1 AS CHAR), 'SINGLE_CHOICE', '下列各句中没有语病的一项是____', '["这里看上去一切正常，市容市貌与其他的乌克兰城镇并无二致。在摄影师皮耶保罗待在切尔诺贝利的那些年里，这种“正常”的感觉让他震惊，他开始用镜头记录切尔诺贝利的日常生活。", "我国已成为世界上第三个实现月球正面软着陆的国家和世界上第一个实现月球背面软着陆的国家，这些成绩的取得，离不开我国探月团队长期以来的拼搏与创新。", "根据公开资料显示，梁寨镇周楼小学位于丰县东南端，距离丰县50余公里，服务区域内人口7000人，教职工只有16人，其中本科学历仅6人。", "作为全球货物贸易第一大国，中国继续保持外贸竞争力，创新产品不仅敲开了新市场的大门，在传统农业向现代食品工业转变中诞生的新兴绿色产业也同样市场广阔。"]', 'B', '参考答案：B。本题考查病句辨析，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列各句中没有语病的一项是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_2 AS CHAR), 'SINGLE_CHOICE', '下列句子顺序排列最恰当的一项是____\n①一方面，以娱乐为职能的大众文化得到蓬勃发展的机会。 \n②与此同时，文化领域却有全然不同的景观。\n③问题是怎样产生的呢?\n④九十年代的中国，商品大潮汹涌而起，给社会经济生活带来无限生机。\n⑤一方面，一部分“曲高和寡“的精英文化，则陷入举步维艰的境地。\n⑥原因有多方面，其中之一就是文化的二重性。', '["④②①⑤③⑥", "③⑥①⑤④②", "④①⑤②③⑥", "④③⑤①②⑥"]', 'A', '参考答案：A。本题考查语言连贯与排序，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列句子顺序排列最恰当的一项是____\n①一方面，以娱乐为职能的大众文化得到蓬勃发展的机会。 \n②与此同时，文化领域却有全然不同的景观。\n③问题是怎样产生的呢?\n④九十年代的中国，商品大潮汹涌而起，给社会经济生活带来无限生机。\n⑤一方面，一部分“曲高和寡“的精英文化，则陷入举步维艰的境地。\n⑥原因有多方面，其中之一就是文化的二重性。');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_3 AS CHAR), 'SINGLE_CHOICE', '下列句中标点符号正确的一项是____', '["原子弹、氢弹的爆炸、人造卫星的发射和回收，标志着我国科技的发展达到了世界先进水平。", "推开窗户一看，呀，流云散了，树叶上的残滴，映着月儿，好似萤光千点，闪闪烁烁地动着。", "这次云南丽江地震的捐款，据不完全统计：高三年级捐了862元，高二年级捐了754元，而高一年级则多达1584元，同学们十分踊跃。", "电视以自己强大的冲击力，推出了众多的引人注目的明星——歌星、舞星、体坛健将、商界名人等等。"]', 'D', '参考答案：D。本题考查标点符号，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列句中标点符号正确的一项是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_1 AS CHAR), 'SINGLE_CHOICE', '下列句子中，没有语病的一句是____', '["正因为科学是一把“双刃剑”，所以，先进的医疗技术既有可能解除病人的痛苦，也有可能对病症束手无策。", "与打电话相比，使用短信可以避免因措辞不当带来的尴尬和窘迫，也不必因害怕失态而刻意控制情绪，因而沟通起来更加轻松随意。", "傅雷先生谈到自己十三岁开始学习法文的经历时说，老师既有教的方法问题，也有自己念得不用功的原因，因此成绩很糟，十分之九已忘了。", "北京将以何种方式来展示我们古老民族参与国际现代事务的能力呢？刘淇回应奥运场馆崇洋时说：节俭办奥运是我们的一贯原则。"]', 'B', '参考答案：B。本题考查病句辨析，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列句子中，没有语病的一句是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_2 AS CHAR), 'SINGLE_CHOICE', '依次填入下面横线处的句子，与上下文衔接最恰当的一组是____\n我独坐在书斋中，忘记了尘世间一切不愉快的事情，怡然自得。以世界之广，宇宙之大，此时却仿佛只有我和我的书友存在。____，____，____，____。\n①阳光照在玉兰花的肥大的绿叶子上\n②连平常我喜欢听的鸟鸣声“光棍好过”，也听而不闻了\n③窗外粼粼碧水，丝丝垂柳\n④这都是我平常最喜爱的东西，现在也都视而不见了', '["③①④②", "①②③④", "①③④②", "③④①②"]', 'A', '参考答案：A。本题考查语言连贯与排序，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '依次填入下面横线处的句子，与上下文衔接最恰当的一组是____\n我独坐在书斋中，忘记了尘世间一切不愉快的事情，怡然自得。以世界之广，宇宙之大，此时却仿佛只有我和我的书友存在。____，____，____，____。\n①阳光照在玉兰花的肥大的绿叶子上\n②连平常我喜欢听的鸟鸣声“光棍好过”，也听而不闻了\n③窗外粼粼碧水，丝丝垂柳\n④这都是我平常最喜爱的东西，现在也都视而不见了');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_3 AS CHAR), 'SINGLE_CHOICE', '下列各句中标点符号使用正确的一句是____', '["不要以为只有葡萄、苹果才能称其为佳果，还有荔枝、桃子、石榴、芒果等许许多多的水果呢。", "有钱的人开着上亿的跑车在街上狂飙，穷人为了获得几斤米却去卖血。这是讽刺还是批评，不论是什么，那些“富人”是否该向“穷人”伸出援助之手呢。", "大量事实证明：爱国主义教育激发了学生学习的积极性，所以要经常进行爱国主义教育。", "中国20岁的女作家登上了《时代周刊》的封面，吉布斯表示（该刊资深编辑），这只是体现了当选人物的新闻性，并不一定是一种荣耀。"]', 'A', '参考答案：A。本题考查标点符号，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列各句中标点符号使用正确的一句是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_chinese, CAST(@kp_chinese_1 AS CHAR), 'SINGLE_CHOICE', '下列句子没有语病的一项是：____', '["文化部将出资购买思想性、艺术性和观赏性俱佳的优秀儿童剧目的著作权，无偿提供给全国基层艺术院团演出。", "我们虽然至今还不能够弄清“莫扎特效应”的奥秘是什么，但是莫扎特音乐在提高人的学习和记忆能力上的作用是毋庸置疑的。", "在上海国际汽车展上，国产新车不断层出不穷，其中国内汽车生产企业拥有完全自主知识产权的车有十多种，是历届车展中最多的。", "自今年二月份中国十部委联合开展网吧等互联网上网服务营业场所专项整治以来，中国共取缔了八千六百多家黑网吧，严查了一批违法接纳未成人进入网吧。"]', 'B', '参考答案：B。本题考查病句辨析，需要结合语境、语言规范和选项表述逐项辨析。', 3, 'smart_learning.sql精选-语文', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_chinese AND source = 'smart_learning.sql精选-语文' AND content = '下列句子没有语病的一项是：____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_1 AS CHAR), 'SINGLE_CHOICE', '阅读下面短文，从短文后各题所给的A、B、C、D四个选项中选出可以填入空白处的最佳选项。\n\nI was walking home from school when I saw a little dog sitting by the road. It looked cold and hungry. I decided to take it home. My mother was surprised to see the dog, but she agreed to let it stay. We gave it some food and water. The dog wagged its tail and seemed very happy. From that day on, the dog became a member of our family.\n\nWhat did the writer do when he saw the dog?', '["He walked away.", "He took it home.", "He called the police.", "He gave it to a friend."]', 'B', '根据短文第二句''I decided to take it home''可知，作者决定把狗带回家。选项A与原文相反；选项C和D在文中未提及。因此正确答案是B。', 2, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = '阅读下面短文，从短文后各题所给的A、B、C、D四个选项中选出可以填入空白处的最佳选项。\n\nI was walking home from school when I saw a little dog sitting by the road. It looked cold and hungry. I decided to take it home. My mother was surprised to see the dog, but she agreed to let it stay. We gave it some food and water. The dog wagged its tail and seemed very happy. From that day on, the dog became a member of our family.\n\nWhat did the writer do when he saw the dog?');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_2 AS CHAR), 'SINGLE_CHOICE', '阅读下面短文，从短文后各题所给的A、B、C、D四个选项中选出可以填入空白处的最佳选项。\n\nMany people think that success is only about money or fame. However, true success is about happiness and fulfillment. For example, a teacher who helps students learn and grow is successful, even if he or she is not rich. A doctor who saves lives is also successful. Success is not measured by what you have, but by what you give to others.\n\nAccording to the passage, what is true success?', '["Having a lot of money.", "Being famous.", "Helping others and feeling happy.", "Having a big house."]', 'C', '根据短文第二句''true success is about happiness and fulfillment''以及最后一句''Success is not measured by what you have, but by what you give to others''可知，真正的成功是给予他人并感到快乐。选项A、B、D都是关于物质财富，与作者观点相反。因此正确答案是C。', 3, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = '阅读下面短文，从短文后各题所给的A、B、C、D四个选项中选出可以填入空白处的最佳选项。\n\nMany people think that success is only about money or fame. However, true success is about happiness and fulfillment. For example, a teacher who helps students learn and grow is successful, even if he or she is not rich. A doctor who saves lives is also successful. Success is not measured by what you have, but by what you give to others.\n\nAccording to the passage, what is true success?');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_3 AS CHAR), 'SINGLE_CHOICE', 'The book ______ by Mo Yan is very popular.', '["written", "was written", "writing", "writes"]', 'A', '本题考查过去分词作定语。book与write之间是被动关系，且动作已完成，因此用过去分词written作后置定语，相当于which was written。故选A。', 3, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'The book ______ by Mo Yan is very popular.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_4 AS CHAR), 'SINGLE_CHOICE', 'The book ______ you lent me yesterday is very interesting.', '["which", "who", "whom", "what"]', 'A', '本题考查定语从句关系代词的选择。先行词是book（物），在从句中作lent的宾语，因此用which或that。选项B和C用于指人，D不用于定语从句。', 2, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'The book ______ you lent me yesterday is very interesting.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_5 AS CHAR), 'SINGLE_CHOICE', 'I don''t know if he ______ tomorrow. If he ______, I will call you.', '["comes; comes", "will come; comes", "comes; will come", "will come; will come"]', 'B', '本题考查if引导的宾语从句和条件状语从句的时态。第一个if是''是否''，引导宾语从句，根据tomorrow用一般将来时will come；第二个if是''如果''，引导条件状语从句，主句用将来时，从句用一般现在时表示将来，因此用comes。故选B。', 4, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'I don''t know if he ______ tomorrow. If he ______, I will call you.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_6 AS CHAR), 'SINGLE_CHOICE', 'The new bridge ______ by the end of next year.', '["will complete", "will be completed", "has completed", "is completing"]', 'B', '本题考查将来时的被动语态。主语''bridge''与''complete''之间为被动关系，且时间状语''by the end of next year''表示将来，因此应用将来时的被动语态''will be completed''。故选B。', 3, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'The new bridge ______ by the end of next year.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_7 AS CHAR), 'SINGLE_CHOICE', 'The new policy is intended to ______ the gap between the rich and the poor.', '["narrow", "shorten", "reduce", "decrease"]', 'A', '本题考查动词辨析。narrow the gap是固定搭配，意为''缩小差距''。shorten通常指长度或时间的缩短；reduce和decrease虽然也有减少的意思，但narrow更形象地表示差距的缩小。', 2, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'The new policy is intended to ______ the gap between the rich and the poor.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_8 AS CHAR), 'SINGLE_CHOICE', '— Would you like some more coffee? — ______. I''m full.', '["Yes, please", "No, thanks", "I''d love to", "Sure, go ahead"]', 'B', '根据答语 ''I''m full''（我饱了）可知，应拒绝对方提供的咖啡。选项 B ''No, thanks'' 是礼貌拒绝的常用表达。A、C、D 均表示接受，与语境矛盾。', 2, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = '— Would you like some more coffee? — ______. I''m full.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_9 AS CHAR), 'SINGLE_CHOICE', 'By the time he arrived at the station, the train ______ for ten minutes.', '["had left", "had been away", "has left", "was leaving"]', 'B', '本题考查过去完成时与持续性动词的用法。''by the time he arrived''表示过去的时间点，动作发生在该时间点之前，应用过去完成时。''leave''是瞬间动词，不能与''for ten minutes''连用，需改为''be away''表示状态。因此选B。', 3, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'By the time he arrived at the station, the train ______ for ten minutes.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_1 AS CHAR), 'SINGLE_CHOICE', '阅读下面短文，从短文后各题所给的A、B、C、D四个选项中选出可以填入空白处的最佳选项。\n\nTom was a very lazy boy. He never did his homework on time. One day, his teacher asked him to stay after class. "Tom, why don''t you do your homework?" the teacher asked. Tom looked down and said nothing. The teacher then said, "If you don''t start working hard, you will fail the exam." Tom felt ashamed and promised to change. From then on, he began to do his homework every day.\n\nWhat did the teacher do to Tom?', '["She praised him.", "She asked him to stay after class.", "She gave him a gift.", "She sent him home early."]', 'B', '根据短文第三句''his teacher asked him to stay after class''可知，老师让Tom课后留下来。选项A、C、D均与原文不符。因此正确答案是B。', 2, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = '阅读下面短文，从短文后各题所给的A、B、C、D四个选项中选出可以填入空白处的最佳选项。\n\nTom was a very lazy boy. He never did his homework on time. One day, his teacher asked him to stay after class. "Tom, why don''t you do your homework?" the teacher asked. Tom looked down and said nothing. The teacher then said, "If you don''t start working hard, you will fail the exam." Tom felt ashamed and promised to change. From then on, he began to do his homework every day.\n\nWhat did the teacher do to Tom?');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_2 AS CHAR), 'SINGLE_CHOICE', '阅读下面短文，从短文后各题所给的A、B、C、D四个选项中选出可以填入空白处的最佳选项。\n\nWhen I was a child, I loved to visit my grandmother''s farm. Every summer, I would spend two weeks there. I helped her feed the chickens and collect eggs. One day, I accidentally broke a basket of eggs. I felt terrible and thought she would be angry. But she just smiled and said, "Don''t worry, mistakes happen. Let''s clean it up together." That day, I learned an important lesson about forgiveness.\n\nWhat lesson did the writer learn?', '["How to collect eggs.", "How to be careful.", "The importance of forgiveness.", "The value of hard work."]', 'C', '根据短文最后一句''That day, I learned an important lesson about forgiveness''可知，作者学到了关于宽恕的重要一课。选项A和D是表面行为，选项B是可能的结果但非核心教训。因此正确答案是C。', 3, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = '阅读下面短文，从短文后各题所给的A、B、C、D四个选项中选出可以填入空白处的最佳选项。\n\nWhen I was a child, I loved to visit my grandmother''s farm. Every summer, I would spend two weeks there. I helped her feed the chickens and collect eggs. One day, I accidentally broke a basket of eggs. I felt terrible and thought she would be angry. But she just smiled and said, "Don''t worry, mistakes happen. Let''s clean it up together." That day, I learned an important lesson about forgiveness.\n\nWhat lesson did the writer learn?');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_3 AS CHAR), 'SINGLE_CHOICE', '______ from the top of the mountain, the city looks magnificent.', '["Seeing", "Seen", "To see", "Having seen"]', 'B', '本题考查非谓语动词作状语。主语the city与动词see之间是被动关系，即城市被看见，因此用过去分词Seen表示被动。A选项Seeing表示主动，C选项To see表示目的或将来，D选项Having seen表示主动且完成，均不符合逻辑。', 2, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = '______ from the top of the mountain, the city looks magnificent.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_4 AS CHAR), 'SINGLE_CHOICE', 'This is the factory ______ my father worked ten years ago.', '["which", "that", "where", "what"]', 'C', '本题考查定语从句关系副词。先行词是factory（地点），从句中worked是不及物动词，缺少地点状语，因此用where。选项A和B用于主语或宾语，D不用于定语从句。', 3, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'This is the factory ______ my father worked ten years ago.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_5 AS CHAR), 'SINGLE_CHOICE', 'I don''t know ______ he will come or not.', '["if", "whether", "that", "what"]', 'B', '本题考查宾语从句连接词。在动词know后，表示''是否''时，whether和if均可，但后面有or not时，只能用whether。选项C和D不符合句意。', 3, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'I don''t know ______ he will come or not.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_6 AS CHAR), 'SINGLE_CHOICE', 'The experiment ______ by the students tomorrow afternoon.', '["is done", "will do", "will be done", "has been done"]', 'C', '本题考查将来时的被动语态。主语''experiment''与''do''之间为被动关系，时间状语''tomorrow afternoon''表示将来，因此应用将来时的被动语态。故选C。', 2, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'The experiment ______ by the students tomorrow afternoon.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_7 AS CHAR), 'SINGLE_CHOICE', 'The scientist ______ his research to find a cure for the disease, despite many failures.', '["insisted on", "persisted in", "stuck to", "kept on"]', 'B', '本题考查动词短语辨析。persist in doing sth. 意为''坚持做某事''，强调克服困难继续做。insist on多指坚持主张或要求；stick to多指坚持原则或计划；keep on表示继续做，语气较弱。', 3, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'The scientist ______ his research to find a cure for the disease, despite many failures.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_8 AS CHAR), 'SINGLE_CHOICE', '— I''m sorry I broke your pen. — ______. I have another one.', '["You''re welcome", "That''s right", "Never mind", "Don''t mention it"]', 'C', '对方道歉时，应表示谅解。''Never mind'' 意为 ''没关系''，用于安慰对方。A 用于回答感谢；B 表示 ''正确''；D 虽也可表示 ''不客气''，但更常用于回应感谢，且在此语境中不如 ''Never mind'' 自然。', 2, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = '— I''m sorry I broke your pen. — ______. I have another one.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_9 AS CHAR), 'SINGLE_CHOICE', 'Look! The children ______ in the park now.', '["play", "are playing", "have played", "played"]', 'B', '本题考查现在进行时的用法。句中有时间状语''now''，且''Look!''提示动作正在进行，因此应用现在进行时。故选B。', 2, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'Look! The children ______ in the park now.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_1 AS CHAR), 'SINGLE_CHOICE', '阅读下面短文，从短文后各题所给的A、B、C、D四个选项中选出可以填入空白处的最佳选项。\n\nIt was a rainy day. Sarah was waiting for the bus at the stop. Suddenly, she saw an old man fall down on the street. Without thinking, she ran to help him. She helped him stand up and asked if he was okay. The old man thanked her and said he was just a little dizzy. Sarah waited with him until his family came. Later, the old man''s family sent her a thank-you letter.\n\nWhy did Sarah run to the old man?', '["Because she knew him.", "Because he fell down.", "Because he called her.", "Because she wanted to take his place."]', 'B', '根据短文第三句''she saw an old man fall down on the street''和第四句''Without thinking, she ran to help him''可知，Sarah看到老人摔倒后立刻跑过去帮忙。选项A、C、D在文中没有依据。因此正确答案是B。', 2, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = '阅读下面短文，从短文后各题所给的A、B、C、D四个选项中选出可以填入空白处的最佳选项。\n\nIt was a rainy day. Sarah was waiting for the bus at the stop. Suddenly, she saw an old man fall down on the street. Without thinking, she ran to help him. She helped him stand up and asked if he was okay. The old man thanked her and said he was just a little dizzy. Sarah waited with him until his family came. Later, the old man''s family sent her a thank-you letter.\n\nWhy did Sarah run to the old man?');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_2 AS CHAR), 'SINGLE_CHOICE', '阅读下面短文，从短文后各题所给的A、B、C、D四个选项中选出可以填入空白处的最佳选项。\n\nScientists have found that spending time in nature can improve mental health. For example, walking in a forest can reduce stress and anxiety. Even looking at pictures of nature can have a positive effect. This is because nature helps us relax and focus on the present moment. So, if you feel tired or worried, try to spend some time outdoors.\n\nWhat is the main idea of the passage?', '["Nature can make people sick.", "Nature is good for mental health.", "Walking is the only way to relax.", "Pictures of nature are useless."]', 'B', '根据短文第一句''Spending time in nature can improve mental health''以及后文的举例，可知文章主要说明大自然对心理健康有益。选项A、C、D都与原文相反或过于绝对。因此正确答案是B。', 3, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = '阅读下面短文，从短文后各题所给的A、B、C、D四个选项中选出可以填入空白处的最佳选项。\n\nScientists have found that spending time in nature can improve mental health. For example, walking in a forest can reduce stress and anxiety. Even looking at pictures of nature can have a positive effect. This is because nature helps us relax and focus on the present moment. So, if you feel tired or worried, try to spend some time outdoors.\n\nWhat is the main idea of the passage?');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_3 AS CHAR), 'SINGLE_CHOICE', 'The teacher asked us ______ quiet in the library.', '["keep", "to keep", "keeping", "kept"]', 'B', '本题考查非谓语动词作宾语补足语。动词ask后通常接带to的不定式作宾语补足语，即ask sb. to do sth.，表示“要求某人做某事”。因此正确答案是to keep。A选项keep是动词原形，C选项keeping是现在分词，D选项kept是过去分词，均不符合ask的用法。', 2, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'The teacher asked us ______ quiet in the library.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_4 AS CHAR), 'SINGLE_CHOICE', '______ is known to all, the earth moves around the sun.', '["It", "As", "That", "What"]', 'B', '本题考查非限制性定语从句。as引导非限制性定语从句，指代整个主句，可放在句首。选项A（It）需与that连用构成主语从句，C和D不符合语法。', 4, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = '______ is known to all, the earth moves around the sun.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_5 AS CHAR), 'SINGLE_CHOICE', 'I wonder ______ you can help me with this problem.', '["that", "if", "what", "which"]', 'B', '本题考查宾语从句连接词。动词wonder后表示''是否''，用if或whether。选项A（that）用于陈述句，C和D不符合句意。', 2, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'I wonder ______ you can help me with this problem.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_6 AS CHAR), 'SINGLE_CHOICE', 'The book ______ by a famous writer last year.', '["wrote", "was written", "is written", "has written"]', 'B', '本题考查一般过去时的被动语态。主语''book''与''write''之间为被动关系，时间状语''last year''表示过去，因此应用一般过去时的被动语态。故选B。', 2, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'The book ______ by a famous writer last year.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_7 AS CHAR), 'SINGLE_CHOICE', 'The teacher asked the students to ______ the main points of the lecture in their notebooks.', '["set down", "put down", "take down", "write down"]', 'C', '本题考查动词短语辨析。take down意为''记下、记录''，特指听写或记录讲话内容。set down和write down也都有记录的意思，但take down更强调当场记录；put down通常指放下或写下。', 3, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'The teacher asked the students to ______ the main points of the lecture in their notebooks.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_8 AS CHAR), 'SINGLE_CHOICE', '— Could you tell me how to get to the nearest hospital? — ______. Go straight and turn left.', '["No problem", "Sorry, I''m new here", "Certainly", "Not at all"]', 'C', '问路时，对方给出具体方向，说明愿意提供帮助。''Certainly'' 表示 ''当然可以''，语气礼貌且肯定。A ''No problem'' 虽也可表示同意，但更常用于回应感谢或请求；B 表示不知道路，与后文矛盾；D 用于回答感谢。', 3, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = '— Could you tell me how to get to the nearest hospital? — ______. Go straight and turn left.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_9 AS CHAR), 'SINGLE_CHOICE', 'She ______ English for three years before she went to the UK.', '["has studied", "had studied", "studied", "was studying"]', 'B', '本题考查过去完成时的用法。''before she went to the UK''表示过去的时间点，学习英语发生在该时间点之前，即''过去的过去''，因此应用过去完成时。故选B。', 3, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'She ______ English for three years before she went to the UK.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_1 AS CHAR), 'SINGLE_CHOICE', '阅读下面短文，从短文后各题所给的A、B、C、D四个选项中选出可以填入空白处的最佳选项。\n\nIn many cultures, giving gifts is an important way to show respect and love. However, the meaning of gifts can vary. For example, in China, giving a clock is considered bad luck because the word for ''clock'' sounds like ''death''. In Japan, giving four of something is also unlucky because the word for ''four'' sounds like ''death''. Therefore, it is important to understand cultural differences when giving gifts.\n\nWhy is giving a clock considered unlucky in China?', '["Because clocks are expensive.", "Because clocks are not useful.", "Because the word for ''clock'' sounds like ''death''.", "Because people don''t like time."]', 'C', '根据短文第三句''in China, giving a clock is considered bad luck because the word for ''clock'' sounds like ''death''''可知，送钟被认为不吉利是因为谐音。选项A、B、D在文中没有依据。因此正确答案是C。', 3, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = '阅读下面短文，从短文后各题所给的A、B、C、D四个选项中选出可以填入空白处的最佳选项。\n\nIn many cultures, giving gifts is an important way to show respect and love. However, the meaning of gifts can vary. For example, in China, giving a clock is considered bad luck because the word for ''clock'' sounds like ''death''. In Japan, giving four of something is also unlucky because the word for ''four'' sounds like ''death''. Therefore, it is important to understand cultural differences when giving gifts.\n\nWhy is giving a clock considered unlucky in China?');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_2 AS CHAR), 'SINGLE_CHOICE', '阅读下面短文，从短文后各题所给的A、B、C、D四个选项中，选出可以填入空白处的最佳选项。\n\nIn many cultures, the color red has different meanings. In China, red symbolizes good luck and happiness, so it is often used in festivals and weddings. In Western countries, however, red can represent danger or anger. For example, a red traffic light means stop. Understanding these cultural differences is important for effective communication.\n\nWhat does the color red symbolize in China according to the passage?', '["Danger and anger.", "Good luck and happiness.", "Sadness and loss.", "Peace and calm."]', 'B', '文中明确提到''In China, red symbolizes good luck and happiness''。选项A是红色在西方国家的含义；选项C和D文中未提及。', 3, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = '阅读下面短文，从短文后各题所给的A、B、C、D四个选项中，选出可以填入空白处的最佳选项。\n\nIn many cultures, the color red has different meanings. In China, red symbolizes good luck and happiness, so it is often used in festivals and weddings. In Western countries, however, red can represent danger or anger. For example, a red traffic light means stop. Understanding these cultural differences is important for effective communication.\n\nWhat does the color red symbolize in China according to the passage?');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_3 AS CHAR), 'SINGLE_CHOICE', 'I regret ______ you that your application has been rejected.', '["informing", "to inform", "having informed", "inform"]', 'B', '本题考查regret后接非谓语动词的用法。regret to do sth.表示“遗憾地要做某事”（事情未发生），regret doing sth.表示“后悔做了某事”（事情已发生）。根据句意“我遗憾地通知你，你的申请被拒绝了”，通知的动作尚未发生，因此用to inform。A选项informing表示后悔已通知，C选项having informed强调完成，D选项inform是动词原形，均不符合。', 3, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'I regret ______ you that your application has been rejected.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_4 AS CHAR), 'SINGLE_CHOICE', 'The reason ______ he was late is that he missed the bus.', '["why", "which", "that", "what"]', 'A', '本题考查定语从句关系副词。先行词是reason，从句中缺少原因状语，因此用why。选项B和C用于主语或宾语，D不用于定语从句。', 3, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'The reason ______ he was late is that he missed the bus.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_5 AS CHAR), 'SINGLE_CHOICE', 'She told me ______ she had finished her homework.', '["what", "that", "if", "whether"]', 'B', '本题考查宾语从句连接词。动词told后接陈述句，用that引导，that可省略。选项A（what）表示''什么''，C和D表示''是否''，不符合句意。', 2, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'She told me ______ she had finished her homework.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_6 AS CHAR), 'SINGLE_CHOICE', 'The new bridge ______ next year.', '["builds", "is built", "will be built", "is building"]', 'C', '本题考查一般将来时的被动语态。主语The new bridge与build之间是被动关系，且时间状语next year表示将来，因此用一般将来时的被动语态will be built。故选C。', 2, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'The new bridge ______ next year.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_7 AS CHAR), 'SINGLE_CHOICE', 'The company''s profits have ______ dramatically over the past three years.', '["raised", "risen", "arose", "aroused"]', 'B', '本题考查易混动词辨析。rise是不及物动词，意为''上升、增长''，符合语境。raise是及物动词，后面需接宾语；arise意为''出现、产生''；arouse意为''唤起、激起''。', 3, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'The company''s profits have ______ dramatically over the past three years.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_8 AS CHAR), 'SINGLE_CHOICE', '— I''m going to take an exam tomorrow. — ______!', '["Good luck", "Congratulations", "Well done", "Have a good time"]', 'A', '对方即将参加考试，应表达祝愿。''Good luck'' 是考前祝福的常用语。B ''Congratulations'' 用于祝贺成功；C ''Well done'' 用于表扬已完成的事情；D ''Have a good time'' 用于祝愿娱乐活动愉快。', 2, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = '— I''m going to take an exam tomorrow. — ______!');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_9 AS CHAR), 'SINGLE_CHOICE', 'This kind of cloth ______ easily.', '["washes", "is washed", "is washing", "has washed"]', 'A', '本题考查主动形式表示被动含义。某些动词如''wash, read, sell''等，当主语是物且表示主语的特性时，常用主动形式表示被动含义。''This kind of cloth washes easily''意为''这种布料容易洗''。故选A。', 4, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'This kind of cloth ______ easily.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_1 AS CHAR), 'SINGLE_CHOICE', '阅读下面短文，从短文后各题所给的A、B、C、D四个选项中选出可以填入空白处的最佳选项。\n\nEmma was a talented artist, but she was very shy. She never showed her paintings to anyone. One day, her art teacher asked her to participate in a school art competition. Emma was nervous, but she agreed. She worked hard on her painting and submitted it. To her surprise, she won first prize! This experience gave her confidence, and she started sharing her art with others.\n\nWhat did Emma''s teacher ask her to do?', '["To stop painting.", "To join a competition.", "To teach other students.", "To sell her paintings."]', 'B', '根据短文第三句''her art teacher asked her to participate in a school art competition''可知，老师让她参加比赛。选项A、C、D与原文不符。因此正确答案是B。', 2, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = '阅读下面短文，从短文后各题所给的A、B、C、D四个选项中选出可以填入空白处的最佳选项。\n\nEmma was a talented artist, but she was very shy. She never showed her paintings to anyone. One day, her art teacher asked her to participate in a school art competition. Emma was nervous, but she agreed. She worked hard on her painting and submitted it. To her surprise, she won first prize! This experience gave her confidence, and she started sharing her art with others.\n\nWhat did Emma''s teacher ask her to do?');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_2 AS CHAR), 'SINGLE_CHOICE', '阅读下面短文，从短文后各题所给的A、B、C、D四个选项中，选出可以填入空白处的最佳选项。\n\nScientists have discovered that spending time in nature can improve mental health. A study found that people who walked in a forest for 90 minutes had lower levels of stress hormones compared to those who walked in a city. The researchers believe that the sights and sounds of nature help calm the mind. This is why more doctors are now prescribing ''nature therapy'' to their patients.\n\nWhat is the main finding of the study mentioned in the passage?', '["Walking in a city is better for health.", "Forest walking reduces stress more than city walking.", "Nature therapy is only for mental patients.", "Stress hormones are not affected by environment."]', 'B', '文中指出''people who walked in a forest for 90 minutes had lower levels of stress hormones compared to those who walked in a city''，因此森林散步比城市散步更能减轻压力。选项A与结果相反；选项C和D与原文信息不符。', 4, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = '阅读下面短文，从短文后各题所给的A、B、C、D四个选项中，选出可以填入空白处的最佳选项。\n\nScientists have discovered that spending time in nature can improve mental health. A study found that people who walked in a forest for 90 minutes had lower levels of stress hormones compared to those who walked in a city. The researchers believe that the sights and sounds of nature help calm the mind. This is why more doctors are now prescribing ''nature therapy'' to their patients.\n\nWhat is the main finding of the study mentioned in the passage?');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_3 AS CHAR), 'SINGLE_CHOICE', 'The boy ______ in the corner is my brother.', '["crying", "cried", "to cry", "having cried"]', 'A', '本题考查非谓语动词作定语。现在分词crying表示主动且正在进行的动作，修饰名词the boy，意为“正在角落哭的男孩”。B选项cried是过去分词，表示被动或完成，但男孩哭是主动动作；C选项to cry表示将来或目的；D选项having cried强调完成，但此处强调正在进行的动作，因此A正确。', 2, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'The boy ______ in the corner is my brother.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_4 AS CHAR), 'SINGLE_CHOICE', 'The man ______ is standing over there is my teacher.', '["which", "whom", "who", "what"]', 'C', '本题考查定语从句关系代词。先行词是man（人），在从句中作主语，因此用who。选项A用于物，B用于宾语，D不用于定语从句。', 2, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'The man ______ is standing over there is my teacher.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_5 AS CHAR), 'SINGLE_CHOICE', 'The teacher told us that the earth ______ around the sun.', '["moves", "moved", "has moved", "was moving"]', 'A', '本题考查宾语从句中时态的用法。当主句为过去时，从句通常用相应的过去时态，但表示客观真理或自然现象时，从句仍用一般现在时。''地球绕太阳转''是客观真理，所以用一般现在时moves。选项B moved是过去时，错误；选项C has moved是现在完成时；选项D was moving是过去进行时。', 2, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'The teacher told us that the earth ______ around the sun.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_6 AS CHAR), 'SINGLE_CHOICE', 'The windows ______ every day.', '["clean", "are cleaned", "are cleaning", "cleaned"]', 'B', '本题考查一般现在时的被动语态。主语The windows与clean之间是被动关系，且every day表示经常性动作，因此用一般现在时的被动语态are cleaned。故选B。', 2, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'The windows ______ every day.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_7 AS CHAR), 'SINGLE_CHOICE', 'The two countries have ______ a trade agreement that will benefit both economies.', '["entered", "entered into", "entered for", "entered on"]', 'B', '本题考查动词短语辨析。enter into an agreement是固定搭配，意为''达成协议、签订协议''。enter单独使用表示进入；enter for表示报名参加；enter on表示开始、着手。', 3, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'The two countries have ______ a trade agreement that will benefit both economies.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_8 AS CHAR), 'SINGLE_CHOICE', '— Thank you for helping me with my English. — ______.', '["With pleasure", "It''s my pleasure", "That''s all right", "All of the above"]', 'D', '回答感谢时，''With pleasure''（乐意效劳）、''It''s my pleasure''（这是我的荣幸）、''That''s all right''（没关系）均为正确表达。因此 D ''All of the above'' 是正确答案。注意：''With pleasure'' 侧重表示愿意帮忙，''It''s my pleasure'' 更正式，''That''s all right'' 较随意。', 4, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = '— Thank you for helping me with my English. — ______.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_9 AS CHAR), 'SINGLE_CHOICE', 'I ______ my homework when my mother came back.', '["do", "am doing", "was doing", "have done"]', 'C', '本题考查过去进行时的用法。''when my mother came back''表示一个过去的时间点，在该时间点正在进行的动作用过去进行时。故选C。', 2, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'I ______ my homework when my mother came back.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_1 AS CHAR), 'SINGLE_CHOICE', '阅读下面短文，从短文后各题所给的A、B、C、D四个选项中选出可以填入空白处的最佳选项。\n\nTechnology has changed the way we communicate. In the past, people wrote letters to stay in touch. Now, we use emails, text messages, and social media. While these tools are fast and convenient, some people argue that they make communication less personal. For example, a text message cannot show the emotion in someone''s voice. Therefore, it is important to balance technology with face-to-face communication.\n\nWhat is the disadvantage of modern communication tools according to the passage?', '["They are too slow.", "They are expensive.", "They are less personal.", "They are difficult to use."]', 'C', '根据短文第四句''some people argue that they make communication less personal''可知，现代通讯工具的缺点是缺乏人情味。选项A、B、D与原文相反或未提及。因此正确答案是C。', 3, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = '阅读下面短文，从短文后各题所给的A、B、C、D四个选项中选出可以填入空白处的最佳选项。\n\nTechnology has changed the way we communicate. In the past, people wrote letters to stay in touch. Now, we use emails, text messages, and social media. While these tools are fast and convenient, some people argue that they make communication less personal. For example, a text message cannot show the emotion in someone''s voice. Therefore, it is important to balance technology with face-to-face communication.\n\nWhat is the disadvantage of modern communication tools according to the passage?');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_3 AS CHAR), 'SINGLE_CHOICE', '______ the project on time, the team worked overtime every day.', '["Completing", "Completed", "To complete", "Having completed"]', 'C', '本题考查非谓语动词作目的状语。不定式To complete表示目的，意为“为了按时完成项目”。A选项Completing表示伴随或主动进行，B选项Completed表示被动，D选项Having completed表示主动完成，均不能表达目的。', 3, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = '______ the project on time, the team worked overtime every day.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_4 AS CHAR), 'SINGLE_CHOICE', 'The house ______ windows are broken is empty.', '["which", "that", "whose", "what"]', 'C', '本题考查定语从句关系代词。先行词是house，从句中windows与house是所属关系，因此用whose。选项A和B用于主语或宾语，D不用于定语从句。', 4, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'The house ______ windows are broken is empty.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_5 AS CHAR), 'SINGLE_CHOICE', 'I don''t know ______ he will come or not tomorrow.', '["if", "whether", "that", "what"]', 'B', '本题考查宾语从句连接词的选择。在动词know后，表示''是否''时，whether和if都可引导宾语从句，但后面有or not时，只能用whether，不能用if。选项A if不能与or not直接连用；选项C that引导陈述句；选项D what引导名词性从句，表示''什么''。', 2, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'I don''t know ______ he will come or not tomorrow.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_english, CAST(@kp_english_6 AS CHAR), 'SINGLE_CHOICE', 'I ______ my keys. I can''t find them anywhere.', '["lost", "have lost", "had lost", "was losing"]', 'B', '本题考查现在完成时。''I can''t find them anywhere''强调对现在造成的影响（找不到钥匙），因此用现在完成时have lost表示过去发生的动作对现在的影响。故选B。', 3, 'smart_learning.sql精选-英语', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_english AND source = 'smart_learning.sql精选-英语' AND content = 'I ______ my keys. I can''t find them anywhere.');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_history, CAST(@kp_history_1 AS CHAR), 'SINGLE_CHOICE', '公元前216年，秦始皇下诏“使黔首（百姓）自实田（上报土地数目）”，这一法令表明秦朝____', '["准备在全国实行土地国有制度", "土地私有制度已经在全国确立", "采取抑制土地兼并的经济政策", "加强了对边远地区的经济控制"]', 'B', '参考答案：B。本题考查中国古代史，需要抓住材料时间、主体和历史背景，排除与史实或材料主旨不符的选项。', 3, 'smart_learning.sql精选-历史', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_history AND source = 'smart_learning.sql精选-历史' AND content = '公元前216年，秦始皇下诏“使黔首（百姓）自实田（上报土地数目）”，这一法令表明秦朝____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_history, CAST(@kp_history_2 AS CHAR), 'SINGLE_CHOICE', '从鸦片战争到八国联军的侵华战争，对中国社会产生了巨大影响，其中不包括：____', '["中国的领土主权完整遭到破坏", "中国被卷入资本主义市场", "客观上推动了中国现代化运动的兴起", "动摇了清朝统治的基础，加速了清王朝的灭亡"]', 'D', '参考答案：D。本题考查中国近代史，需要抓住材料时间、主体和历史背景，排除与史实或材料主旨不符的选项。', 3, 'smart_learning.sql精选-历史', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_history AND source = 'smart_learning.sql精选-历史' AND content = '从鸦片战争到八国联军的侵华战争，对中国社会产生了巨大影响，其中不包括：____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_history, CAST(@kp_history_3 AS CHAR), 'SINGLE_CHOICE', '"一五计划"中，工业规模和农业增产是陈云关注的两件大事，并且他认为搞合作化是实现农业增产的有效途径，可以使农业平均产量提高15%到30%，花钱少、收效快，国家应给予更多的支持。这体现出我国的"一五计划"____', '["优先发展重工业的战略考量", "发展生产力和变革生产关系并举", "工农业生产并举的发展目标", "重点关注了农业增产的核心地位"]', 'B', '参考答案：B。本题考查中国现代史，需要抓住材料时间、主体和历史背景，排除与史实或材料主旨不符的选项。', 3, 'smart_learning.sql精选-历史', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_history AND source = 'smart_learning.sql精选-历史' AND content = '"一五计划"中，工业规模和农业增产是陈云关注的两件大事，并且他认为搞合作化是实现农业增产的有效途径，可以使农业平均产量提高15%到30%，花钱少、收效快，国家应给予更多的支持。这体现出我国的"一五计划"____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_history, CAST(@kp_history_4 AS CHAR), 'SINGLE_CHOICE', '哥伦布在航海日记中记载了巴哈马群岛"全年都可种植和收获玉米以及其他作物。"历史学家艾尔文·约瑟非也说："今日世界食物总量中几乎一半的作物是美洲印第安人种植的，而白人只是在1542年以后才知道它们。"由此可知，新航路的开辟____', '["促进了全球物种的交换", "改变了商业的经营方式", "增加了全球商品的种类", "造成对美洲资源的掠夺"]', 'A', '参考答案：A。本题考查世界古代与中世纪史，需要抓住材料时间、主体和历史背景，排除与史实或材料主旨不符的选项。', 3, 'smart_learning.sql精选-历史', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_history AND source = 'smart_learning.sql精选-历史' AND content = '哥伦布在航海日记中记载了巴哈马群岛"全年都可种植和收获玉米以及其他作物。"历史学家艾尔文·约瑟非也说："今日世界食物总量中几乎一半的作物是美洲印第安人种植的，而白人只是在1542年以后才知道它们。"由此可知，新航路的开辟____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_history, CAST(@kp_history_5 AS CHAR), 'SINGLE_CHOICE', '一战期间和南京国民政府统治前期是我国近代民族资本主义工业发展的两次高潮时期，请问这两次高潮时期出现的共同原因是指____', '["国际环境有利", "民族独立实现", "社会性质改变", "政府大力支持"]', 'D', '参考答案：D。本题考查近代世界史，需要抓住材料时间、主体和历史背景，排除与史实或材料主旨不符的选项。', 3, 'smart_learning.sql精选-历史', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_history AND source = 'smart_learning.sql精选-历史' AND content = '一战期间和南京国民政府统治前期是我国近代民族资本主义工业发展的两次高潮时期，请问这两次高潮时期出现的共同原因是指____');
