INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_history, CAST(@kp_history_3 AS CHAR), 'SINGLE_CHOICE', '邓小平在《在武昌、深圳、珠海、上海等地的谈话要点》中指出不坚持社会主义，不改革开放.不发展经济，不改善人民生活，只能是死路一条。基本路线要管一百年，动摇不得。……当然，随着实践的发展，该完善的完善，该修补的修补，但总的要坚定不移。”这一谈话____', '["提出了建立市场经济体制的目标", "重新确立了实事求是的思想路线", "推动了我国改革开放进人新阶段", "开辟了中国特色社会主义新道路"]', 'C', '参考答案：C。本题考查中国现代史，需要抓住材料时间、主体和历史背景，排除与史实或材料主旨不符的选项。', 3, 'smart_learning.sql精选-历史', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_history AND source = 'smart_learning.sql精选-历史' AND content = '邓小平在《在武昌、深圳、珠海、上海等地的谈话要点》中指出不坚持社会主义，不改革开放.不发展经济，不改善人民生活，只能是死路一条。基本路线要管一百年，动摇不得。……当然，随着实践的发展，该完善的完善，该修补的修补，但总的要坚定不移。”这一谈话____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_history, CAST(@kp_history_4 AS CHAR), 'SINGLE_CHOICE', '新航路的开辟，“价格革命”之所以能加速资本主义的发展，根本原因是____', '["造成金银价格下降，物价猛涨", "导致市场扩大，流通领域活跃", "从根本上改变了阶级之间的相互关系", "加速了西欧封建制度的衰落"]', 'C', '参考答案：C。本题考查世界古代与中世纪史，需要抓住材料时间、主体和历史背景，排除与史实或材料主旨不符的选项。', 3, 'smart_learning.sql精选-历史', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_history AND source = 'smart_learning.sql精选-历史' AND content = '新航路的开辟，“价格革命”之所以能加速资本主义的发展，根本原因是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_history, CAST(@kp_history_6 AS CHAR), 'SINGLE_CHOICE', '马克思曾指出："土地所有者阶级和劳动者阶级，即封建主和人民衰落了，资本家阶级、资产阶级则相应地上升了。"造成这一现象的主要原因是____', '["商品经济的发展", "商业革命的推动", "价格革命的影响", "天文地理的进步"]', 'C', '参考答案：C。本题考查国际社会主义运动，需要抓住材料时间、主体和历史背景，排除与史实或材料主旨不符的选项。', 3, 'smart_learning.sql精选-历史', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_history AND source = 'smart_learning.sql精选-历史' AND content = '马克思曾指出："土地所有者阶级和劳动者阶级，即封建主和人民衰落了，资本家阶级、资产阶级则相应地上升了。"造成这一现象的主要原因是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_history, CAST(@kp_history_8 AS CHAR), 'SINGLE_CHOICE', '《商君书·农战》中说："言谈游士事君可尊身也、商贾可富家也、技艺足以口也。民见此三者之便且利也，则必去农……国之所兴者农战也……农者寡而游食者众。众，则农者殆；农者殆，则土荒。"由此可见____', '["重农抑商是保护小农经济的权衡之策", "重农抑商政策是商鞅变法的核心措施", "小农经济在经济结构中占据主导地位", "农业的发展势必阻碍商品经济的发展"]', 'A', '参考答案：A。本题考查史料实证与历史解释，需要抓住材料时间、主体和历史背景，排除与史实或材料主旨不符的选项。', 3, 'smart_learning.sql精选-历史', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_history AND source = 'smart_learning.sql精选-历史' AND content = '《商君书·农战》中说："言谈游士事君可尊身也、商贾可富家也、技艺足以口也。民见此三者之便且利也，则必去农……国之所兴者农战也……农者寡而游食者众。众，则农者殆；农者殆，则土荒。"由此可见____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_history, CAST(@kp_history_1 AS CHAR), 'SINGLE_CHOICE', '据记载，到1866年，上海“夷场”“洋楼耸峙，高入云霄，八面窗根，玻璃五色，铁栏错瓦，玉扇铜环”。这表明当时上海____', '["中外融合民居出现", "民众生活水平的提高", "西方建筑样式的传入", "西方殖民势力的强大"]', 'C', '参考答案：C。本题考查中国古代史，需要抓住材料时间、主体和历史背景，排除与史实或材料主旨不符的选项。', 3, 'smart_learning.sql精选-历史', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_history AND source = 'smart_learning.sql精选-历史' AND content = '据记载，到1866年，上海“夷场”“洋楼耸峙，高入云霄，八面窗根，玻璃五色，铁栏错瓦，玉扇铜环”。这表明当时上海____');
