INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_history, CAST(@kp_history_6 AS CHAR), 'SINGLE_CHOICE', '马克思曾指出，运用《共产党宣言》原理“随时随地都要以当时的历史条件为转移”。下列事件可以作为上述观点证据的是____\n  ①正义者同盟建立		②十月革命的胜利\n  ③苏俄新经济政策		④中国社会主义改造', '["①②③④", "①②④", "②③④", "②③"]', 'C', '参考答案：C。本题考查国际社会主义运动，需要抓住材料时间、主体和历史背景，排除与史实或材料主旨不符的选项。', 3, 'smart_learning.sql精选-历史', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_history AND source = 'smart_learning.sql精选-历史' AND content = '马克思曾指出，运用《共产党宣言》原理“随时随地都要以当时的历史条件为转移”。下列事件可以作为上述观点证据的是____\n  ①正义者同盟建立		②十月革命的胜利\n  ③苏俄新经济政策		④中国社会主义改造');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_history, CAST(@kp_history_8 AS CHAR), 'SINGLE_CHOICE', '列宁在评价恩格斯的无私精神时指出：“他为他天才的朋友树立了一块永不磨灭的纪念碑。无意之间，他的名字也被镌刻在了上面。”你认为这块永不磨灭的纪念碑是____', '["《神圣家族》", "《德意志意识形态》", "《共产党宣言》", "《资本论》"]', 'D', '参考答案：D。本题考查史料实证与历史解释，需要抓住材料时间、主体和历史背景，排除与史实或材料主旨不符的选项。', 3, 'smart_learning.sql精选-历史', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_history AND source = 'smart_learning.sql精选-历史' AND content = '列宁在评价恩格斯的无私精神时指出：“他为他天才的朋友树立了一块永不磨灭的纪念碑。无意之间，他的名字也被镌刻在了上面。”你认为这块永不磨灭的纪念碑是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_history, CAST(@kp_history_1 AS CHAR), 'SINGLE_CHOICE', '当今世界最成功的区域一体化组织非欧盟莫属，她起步于煤钢共同体的建立，发展于欧洲经济共同体，再到欧洲联盟，这说明欧洲联盟____', '["欧洲联盟是当今最重要的国际组织", "欧洲联盟既是经济组织又是政治组织", "欧洲联盟是经济区域集团化的起点", "欧洲联盟的成立彻底改变了世界格局"]', 'B', '参考答案：B。本题考查中国古代史，需要抓住材料时间、主体和历史背景，排除与史实或材料主旨不符的选项。', 3, 'smart_learning.sql精选-历史', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_history AND source = 'smart_learning.sql精选-历史' AND content = '当今世界最成功的区域一体化组织非欧盟莫属，她起步于煤钢共同体的建立，发展于欧洲经济共同体，再到欧洲联盟，这说明欧洲联盟____');
