INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_history, CAST(@kp_history_8 AS CHAR), 'SINGLE_CHOICE', '1921年，有学者对全国631位大学生进行婚姻调查问卷显示，在被调查的184位已婚者中，自定婚姻的只有6人。在对代订婚姻者作出表态的145人中，愿代订的为56人，不愿代订的则为89人。据此可知当时____', '["婚姻礼俗开始删繁就简", "部分青年学生主张婚姻自主", "恋爱自由婚姻自主成为时尚", "辛亥革命移风易俗的成效显著"]', 'B', '参考答案：B。本题考查史料实证与历史解释，需要抓住材料时间、主体和历史背景，排除与史实或材料主旨不符的选项。', 3, 'smart_learning.sql精选-历史', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_history AND source = 'smart_learning.sql精选-历史' AND content = '1921年，有学者对全国631位大学生进行婚姻调查问卷显示，在被调查的184位已婚者中，自定婚姻的只有6人。在对代订婚姻者作出表态的145人中，愿代订的为56人，不愿代订的则为89人。据此可知当时____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_history, CAST(@kp_history_1 AS CHAR), 'SINGLE_CHOICE', '《史记》.《汉书》凡提及汉朝制度，不管是从政治经济，还是文化学术，必首标汉承秦制，如“汉因循秦制而未改”，“汉承秦制”，“汉初因秦法”，诸如此类，不胜枚举。这说明秦汉时期____', '["官方意识形态一致", "政府注重强化思想控制", "社会演进趋势相同", "统一多民族国家日益发展"]', 'C', '参考答案：C。本题考查中国古代史，需要抓住材料时间、主体和历史背景，排除与史实或材料主旨不符的选项。', 3, 'smart_learning.sql精选-历史', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_history AND source = 'smart_learning.sql精选-历史' AND content = '《史记》.《汉书》凡提及汉朝制度，不管是从政治经济，还是文化学术，必首标汉承秦制，如“汉因循秦制而未改”，“汉承秦制”，“汉初因秦法”，诸如此类，不胜枚举。这说明秦汉时期____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_history, CAST(@kp_history_4 AS CHAR), 'SINGLE_CHOICE', '古希腊的先哲们留给后世许多至理名言。下列名言属于亚里士多德的是____', '["“人是万物的尺度”", "“美德即知识”", "“人非工具”", "“吾爱吾师，吾尤爱真理”"]', 'D', '参考答案：D。本题考查世界古代与中世纪史，需要抓住材料时间、主体和历史背景，排除与史实或材料主旨不符的选项。', 3, 'smart_learning.sql精选-历史', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_history AND source = 'smart_learning.sql精选-历史' AND content = '古希腊的先哲们留给后世许多至理名言。下列名言属于亚里士多德的是____');
