INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_history, CAST(@kp_history_1 AS CHAR), 'SINGLE_CHOICE', '1986年《单一欧洲文件》执行后，欧共体立法程序中超国家权限大增。执委会主席德洛尔于1988年7月在欧洲议会上宣布，10年后欧共体各国80%的经济、财政和社会立法将出自欧共体。此说法遭到了拥护政府间合作道路的各派人士的猛烈抨击。这一事件说明____', '["欧洲一体化存在分歧", "执委会主导了欧洲一体化", "欧共体矛盾难以调和", "欧共体发展损害国家利益"]', 'A', '参考答案：A。本题考查中国古代史，需要抓住材料时间、主体和历史背景，排除与史实或材料主旨不符的选项。', 3, 'smart_learning.sql精选-历史', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_history AND source = 'smart_learning.sql精选-历史' AND content = '1986年《单一欧洲文件》执行后，欧共体立法程序中超国家权限大增。执委会主席德洛尔于1988年7月在欧洲议会上宣布，10年后欧共体各国80%的经济、财政和社会立法将出自欧共体。此说法遭到了拥护政府间合作道路的各派人士的猛烈抨击。这一事件说明____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_history, CAST(@kp_history_4 AS CHAR), 'SINGLE_CHOICE', '有学者指出，早期古希腊哲学中，虽然人性以一种遮蔽的状态呈现，但人们总是想着在与人息息相关的自然界中找到人之根、人之本，哲学家们也开始考虑如何摆脱神的束缚，寻求人的自由。这反映出古希腊早期哲学____', '["提出了衡量世界的尺度", "摆脱了原始宗教的束缚", "奠定了人文精神的基础", "促进了对自然规律的探索"]', 'C', '参考答案：C。本题考查世界古代与中世纪史，需要抓住材料时间、主体和历史背景，排除与史实或材料主旨不符的选项。', 3, 'smart_learning.sql精选-历史', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_history AND source = 'smart_learning.sql精选-历史' AND content = '有学者指出，早期古希腊哲学中，虽然人性以一种遮蔽的状态呈现，但人们总是想着在与人息息相关的自然界中找到人之根、人之本，哲学家们也开始考虑如何摆脱神的束缚，寻求人的自由。这反映出古希腊早期哲学____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_history, CAST(@kp_history_8 AS CHAR), 'SINGLE_CHOICE', '亚历山大二世改革以前，俄国面临着严重危机，主要表现在____\n  ①克里木战争失败				②农奴制的存在严重阻碍了工业的发展\n  ③“十二月党人”起义			④各阶层强烈要求废除农奴制', '["①③", "①②③", "①②③④", "①③④"]', 'B', '参考答案：B。本题考查史料实证与历史解释，需要抓住材料时间、主体和历史背景，排除与史实或材料主旨不符的选项。', 3, 'smart_learning.sql精选-历史', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_history AND source = 'smart_learning.sql精选-历史' AND content = '亚历山大二世改革以前，俄国面临着严重危机，主要表现在____\n  ①克里木战争失败				②农奴制的存在严重阻碍了工业的发展\n  ③“十二月党人”起义			④各阶层强烈要求废除农奴制');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_history, CAST(@kp_history_1 AS CHAR), 'SINGLE_CHOICE', '中国古代瓷器生产技术高超，咏“瓷”诗句众多。如：“九秋风露越窑开，夺得千峰翠色来”、“大邑烧瓷轻且坚，扣如哀玉锦城传。君家白碗胜霜雪，急送茅斋也可怜。”诗中的“越窑”和“大邑”分别以生产什么瓷器出名____', '["青瓷、粉彩瓷器", "粉彩瓷器、白瓷", "青瓷、白瓷", "白瓷、青瓷"]', 'C', '参考答案：C。本题考查中国古代史，需要抓住材料时间、主体和历史背景，排除与史实或材料主旨不符的选项。', 3, 'smart_learning.sql精选-历史', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_history AND source = 'smart_learning.sql精选-历史' AND content = '中国古代瓷器生产技术高超，咏“瓷”诗句众多。如：“九秋风露越窑开，夺得千峰翠色来”、“大邑烧瓷轻且坚，扣如哀玉锦城传。君家白碗胜霜雪，急送茅斋也可怜。”诗中的“越窑”和“大邑”分别以生产什么瓷器出名____');
