INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_geography, CAST(@kp_geography_9 AS CHAR), 'SINGLE_CHOICE', '关于海水运动的叙述，正确的是____', '["风浪、海啸、洋流是海水运动的三种主要形式", "海啸是风浪强烈发展的一种形式，给人类带来了巨大的能量", "潮汐是海水在日月引力作用下发生的周期性涨落现象", "早晨的海水上涨称为潮，晚上的海水下落称为汐"]', 'C', '参考答案：C。本题考查自然地理综合，需要结合区域背景、自然或人文地理规律，对选项进行综合判断。', 3, 'smart_learning.sql精选-地理', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_geography AND source = 'smart_learning.sql精选-地理' AND content = '关于海水运动的叙述，正确的是____');
