INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_1 AS CHAR), 'SINGLE_CHOICE', '物质和意识的关系是____', '["意识决定物质，意识是物质的反映", "物质和意识相互制约、相互作用", "物质离不开意识，意识也离不开物质", "物质决定意识，意识对物质具有能动作用"]', 'D', '参考答案：D。本题考查唯物论与认识论，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '物质和意识的关系是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_2 AS CHAR), 'SINGLE_CHOICE', '财政教育经费投入不足，是长期以来制约我国教育事业发展的一个重要因素。面对这一问题，假如你是人大代表，你可以____', '["行使立法权，完善有关财政教育经费投入的法律法规", "行使决定权，统筹规划各级政府的财政教育经费投入", "行使提案权，联名其他代表制定财政教育经费使用计划", "行使质询权，督促各级政府依法落实财政教育经费投入"]', 'D', '参考答案：D。本题考查辩证法，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '财政教育经费投入不足，是长期以来制约我国教育事业发展的一个重要因素。面对这一问题，假如你是人大代表，你可以____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_3 AS CHAR), 'SINGLE_CHOICE', '参加抗击新冠肺炎疫情的医护人员有一半是“90 后”“00 后”。他们有一句话感动了全国：2003 年“非典”，你们保护了我们；这一次，轮到我们来保护你们了。这表明____\n①相互奉献是实现人生价值的前提\n②价值的实现需要特殊的方式和时机\n③在个人和社会的统一中实现价值\n④实现价值需要正确的价值观的指引', '["①②", "①④", "②③", "③④"]', 'D', '参考答案：D。本题考查社会历史观与价值观，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '参加抗击新冠肺炎疫情的医护人员有一半是“90 后”“00 后”。他们有一句话感动了全国：2003 年“非典”，你们保护了我们；这一次，轮到我们来保护你们了。这表明____\n①相互奉献是实现人生价值的前提\n②价值的实现需要特殊的方式和时机\n③在个人和社会的统一中实现价值\n④实现价值需要正确的价值观的指引');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_4 AS CHAR), 'SINGLE_CHOICE', '春花、夏雨、秋叶、冬雪，配上红墙琉璃瓦，紫禁城的四时皆为诗意美景。近日“二十四节气时光皮肤”【故宫·岁时】上线，该产品将故宫的一年四季与键盘背景绑定，键盘不仅能跟随时间变化，还可展示故宫节气的文化、礼俗、习俗等。这种别具一格的键盘皮肤完全符合年轻人的个性化表达方式，为用户带来更加极致化的输入体验与文化加持。总之，紫禁城的寒来暑往在用户每一次敲击键盘下更加深入于心，可见____\n①文化美学必须依托科技创新\n②文化传播可以用新的形式呈现\n③文化传承以满足个性化的文化体验为目的\n④文化情怀的营造不仅关注内容也要兼顾形式', '["①②", "①③", "②④", "③④"]', 'C', '参考答案：C。本题考查文化传承与创新，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '春花、夏雨、秋叶、冬雪，配上红墙琉璃瓦，紫禁城的四时皆为诗意美景。近日“二十四节气时光皮肤”【故宫·岁时】上线，该产品将故宫的一年四季与键盘背景绑定，键盘不仅能跟随时间变化，还可展示故宫节气的文化、礼俗、习俗等。这种别具一格的键盘皮肤完全符合年轻人的个性化表达方式，为用户带来更加极致化的输入体验与文化加持。总之，紫禁城的寒来暑往在用户每一次敲击键盘下更加深入于心，可见____\n①文化美学必须依托科技创新\n②文化传播可以用新的形式呈现\n③文化传承以满足个性化的文化体验为目的\n④文化情怀的营造不仅关注内容也要兼顾形式');
