INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_6 AS CHAR), 'SINGLE_CHOICE', '与十一届全国人大相比，十二届全国人大的代表组成结构进一步优化。来自基层的工人、农民代表401名，专业技术人员代表610名，分别提高了5.18%.1.2%，党.政领导干部代表1042名，降低了6.93%。这一变化有利于____', '["加强人大与基层群众的联系", "转变政府的基本职能", "提高人民代表大会的决策效率", "保证人民群众直接参加国家管理"]', 'A', '参考答案：A。本题考查政治制度与法治，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '与十一届全国人大相比，十二届全国人大的代表组成结构进一步优化。来自基层的工人、农民代表401名，专业技术人员代表610名，分别提高了5.18%.1.2%，党.政领导干部代表1042名，降低了6.93%。这一变化有利于____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_8 AS CHAR), 'SINGLE_CHOICE', '2012年5月份，教师老王刚领到4200元绩效工资，就在商场购买了一件打折商品，原标价为人民币100元，实际支付80元。在这里，100元、80元分别执行的货币职能是____', '["支付手段、流通手段", "价值尺度、流通手段", "价值尺度、支付手段", "流通手段、价值尺度"]', 'B', '参考答案：B。本题考查政治综合，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '2012年5月份，教师老王刚领到4200元绩效工资，就在商场购买了一件打折商品，原标价为人民币100元，实际支付80元。在这里，100元、80元分别执行的货币职能是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_1 AS CHAR), 'SINGLE_CHOICE', '2012年经济工作会议强调“强农惠农的思想认识只能增强不能削弱，强农惠农的政策力度只能加大不能减小。”这因为：____\n①农业在国民经济中处于基础地位 ②农业是物质资料生产最基本的部门\n③农业在国民经济中处于主导的地位 ④农业是解决劳动力就业的根本渠道', '["①②", "①", "②③", "③④"]', 'A', '参考答案：A。本题考查唯物论与认识论，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '2012年经济工作会议强调“强农惠农的思想认识只能增强不能削弱，强农惠农的政策力度只能加大不能减小。”这因为：____\n①农业在国民经济中处于基础地位 ②农业是物质资料生产最基本的部门\n③农业在国民经济中处于主导的地位 ④农业是解决劳动力就业的根本渠道');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_2 AS CHAR), 'SINGLE_CHOICE', '“事不公则心不平，心不平则气不顺，气不顺则难和谐。”在推动我国经济社会发展的过程中，必须深入推进收入分配制度改革，正确处理好效率与公平的关系。这就要求我们做到____\n①既要落实分配政策，又要提倡奉献精神\n②既要鼓励创业致富，又要倡导回报社会\n③既要反对平均主义，又要反对收入差距\n④初次分配注重效率，再分配中强调公平', '["①②", "③④", "②③", "①④"]', 'A', '参考答案：A。本题考查辩证法，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '“事不公则心不平，心不平则气不顺，气不顺则难和谐。”在推动我国经济社会发展的过程中，必须深入推进收入分配制度改革，正确处理好效率与公平的关系。这就要求我们做到____\n①既要落实分配政策，又要提倡奉献精神\n②既要鼓励创业致富，又要倡导回报社会\n③既要反对平均主义，又要反对收入差距\n④初次分配注重效率，再分配中强调公平');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_3 AS CHAR), 'SINGLE_CHOICE', '中国工程院陈薇院士多年来从事防疫工作，对人类卫生健康事业做出了重要贡献。有人问她：“您天天跟病毒打交道，怕过吗？”陈薇回答：“要说不怕，那可不是真心话……如果我们承担了更多的怕，你和其他人可能就少一点怕。”这启示我们____\n①价值观是人生的重要向导，指引人们选择人生道路\n②投身社会为人民服务是实现人生价值的必由之路\n③价值观是衡量价值判断正确与否的尺度\n④正确的价值判断以正确的价值选择为基础', '["①②", "①③", "②④", "③④"]', 'A', '参考答案：A。本题考查社会历史观与价值观，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '中国工程院陈薇院士多年来从事防疫工作，对人类卫生健康事业做出了重要贡献。有人问她：“您天天跟病毒打交道，怕过吗？”陈薇回答：“要说不怕，那可不是真心话……如果我们承担了更多的怕，你和其他人可能就少一点怕。”这启示我们____\n①价值观是人生的重要向导，指引人们选择人生道路\n②投身社会为人民服务是实现人生价值的必由之路\n③价值观是衡量价值判断正确与否的尺度\n④正确的价值判断以正确的价值选择为基础');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_4 AS CHAR), 'SINGLE_CHOICE', '近年来，上海市政府新建疗养院、文化馆、图书馆、运动场、体育馆等设施供劳动者享用，改善劳动者的生活。这表明上海市政府尊重劳动者的：____\n①取得劳动报酬权 ②休息休假权\n③获得劳动保护权 ④享受社会福利权', '["①②③④", "②③④", "①③", "②④"]', 'D', '参考答案：D。本题考查文化传承与创新，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '近年来，上海市政府新建疗养院、文化馆、图书馆、运动场、体育馆等设施供劳动者享用，改善劳动者的生活。这表明上海市政府尊重劳动者的：____\n①取得劳动报酬权 ②休息休假权\n③获得劳动保护权 ④享受社会福利权');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_5 AS CHAR), 'SINGLE_CHOICE', '2012年8月15日，苏宁易购正式启动送货准时性、 退款及时性和退换货效率三大服务保障 项目。只要消费者在苏宁易购购物，以订单系统确认时间为准，除不可抗因素造成的送货延迟外，超出约定时间3天即按照购买商品金额的一定比例进行赔付。苏宁此举的出发点是____', '["为消费者创造安全放心的购物环境", "承担社会责任，维护消费者权益", "为消费者提供质优价廉的商品", "为实现商品的价值创造有利条件"]', 'D', '参考答案：D。本题考查经济生活，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '2012年8月15日，苏宁易购正式启动送货准时性、 退款及时性和退换货效率三大服务保障 项目。只要消费者在苏宁易购购物，以订单系统确认时间为准，除不可抗因素造成的送货延迟外，超出约定时间3天即按照购买商品金额的一定比例进行赔付。苏宁此举的出发点是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_6 AS CHAR), 'SINGLE_CHOICE', '为了防止权力的滥用，我国已初步建立起全面的行政监督体系，它包括行政系统外部的监督和行政系统内部的监督。下列属于行政系统外部监督的是____\n①国家权力机关的监督   ②司法机关的监督  \n③审计部门的监督       ④社会与公民的监督', '["①②③", "②③④", "①③④", "①②④"]', 'D', '参考答案：D。本题考查政治制度与法治，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '为了防止权力的滥用，我国已初步建立起全面的行政监督体系，它包括行政系统外部的监督和行政系统内部的监督。下列属于行政系统外部监督的是____\n①国家权力机关的监督   ②司法机关的监督  \n③审计部门的监督       ④社会与公民的监督');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_8 AS CHAR), 'SINGLE_CHOICE', '全国劳模徐虎说：“钱可以买到房屋，但买不到家；钱可以买到珠宝，但买不到美；钱可以买到小人之心，但买不到君子之志。”这说明：____', '["金钱不是万能的", "金钱不是财富的象征", "要反对拜金主义", "对待金钱要“取之有道，用之有度”"]', 'A', '参考答案：A。本题考查政治综合，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '全国劳模徐虎说：“钱可以买到房屋，但买不到家；钱可以买到珠宝，但买不到美；钱可以买到小人之心，但买不到君子之志。”这说明：____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_1 AS CHAR), 'SINGLE_CHOICE', '近年来，奉贤区街道干净了、小区整洁了、河道清爽了，空气质量优良率稳居全市第一，城市文明指数测评实现五连冠。而提高生活质量的物质基础是：____', '["精神消费状况", "闲暇时间的多少", "生活环境", "家庭拥有的消费资料和服务产品的数量多少和质量好坏"]', 'D', '参考答案：D。本题考查唯物论与认识论，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '近年来，奉贤区街道干净了、小区整洁了、河道清爽了，空气质量优良率稳居全市第一，城市文明指数测评实现五连冠。而提高生活质量的物质基础是：____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_2 AS CHAR), 'SINGLE_CHOICE', '我国“乐活族”正在悄然发展壮大。“乐活”是近年来出现的一个新词，由“life  styles of health  and  sustainability”的第一个字母组成，直译就是“健康可持续性的生活方式”。“乐活族”在消费时，会考虑到自己和家人的健康以及对生态环境的责任心。“乐活族”的出现表明____\n①人们对精神消费的需求越来越高         ②钱货两清消费成为消费主要方式\n③人们在消费过程中注重商品和服务品质   ④人们的消费行为日趋成熟、理性', '["①④", "②③", "③④", "①②"]', 'C', '参考答案：C。本题考查辩证法，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '我国“乐活族”正在悄然发展壮大。“乐活”是近年来出现的一个新词，由“life  styles of health  and  sustainability”的第一个字母组成，直译就是“健康可持续性的生活方式”。“乐活族”在消费时，会考虑到自己和家人的健康以及对生态环境的责任心。“乐活族”的出现表明____\n①人们对精神消费的需求越来越高         ②钱货两清消费成为消费主要方式\n③人们在消费过程中注重商品和服务品质   ④人们的消费行为日趋成熟、理性');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_3 AS CHAR), 'SINGLE_CHOICE', '经济学上有个古老的原理叫“劣币驱逐良币”：在铸币时代，当那些“劣币”(低于法定重量或者成色的铸币)进入流通领域后，人们就倾向于将那些“良币”(足值货币)收藏起来。结果，市面上“良币”越来越少，“劣币”越来越多。“劣币”之所以能驱逐“良币”，主要是因为____\n①作为流通手段的货币，不一定是足值的货币\n②货币是衡量商品价值的内在尺度\n③交易双方更加关注的是货币的购买力\n④“劣币”作为一种价值符号，能够充当商品交换的媒介', '["①③", "②③", "②④", "①④"]', 'A', '参考答案：A。本题考查社会历史观与价值观，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '经济学上有个古老的原理叫“劣币驱逐良币”：在铸币时代，当那些“劣币”(低于法定重量或者成色的铸币)进入流通领域后，人们就倾向于将那些“良币”(足值货币)收藏起来。结果，市面上“良币”越来越少，“劣币”越来越多。“劣币”之所以能驱逐“良币”，主要是因为____\n①作为流通手段的货币，不一定是足值的货币\n②货币是衡量商品价值的内在尺度\n③交易双方更加关注的是货币的购买力\n④“劣币”作为一种价值符号，能够充当商品交换的媒介');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_4 AS CHAR), 'SINGLE_CHOICE', '长期以来，我国商业银行的运营过于依赖存款规模所形成的垄断利差收益，而余额宝的推出必然造成商业银行存款流失。为应对这一压力，某银行有针对性地推出了理财新产品：按天结息，年化利率略低于余额宝，工作日随用随取。这表明____\n①金融市场的开放有利于促进市场竞争\n②充分的市场竞争有利于促进企业创新\n③商业银行经营目的是为储户提供安全稳定收益\n④垄断损害消费者利益，但对企业是有利的', '["①②", "③④", "①③", "②④"]', 'A', '参考答案：A。本题考查文化传承与创新，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '长期以来，我国商业银行的运营过于依赖存款规模所形成的垄断利差收益，而余额宝的推出必然造成商业银行存款流失。为应对这一压力，某银行有针对性地推出了理财新产品：按天结息，年化利率略低于余额宝，工作日随用随取。这表明____\n①金融市场的开放有利于促进市场竞争\n②充分的市场竞争有利于促进企业创新\n③商业银行经营目的是为储户提供安全稳定收益\n④垄断损害消费者利益，但对企业是有利的');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_5 AS CHAR), 'SINGLE_CHOICE', '2014年4月2日，国务院提出将小微企业减半征收企业所得税优惠政策实施范围上限由年应纳税所得额6万元进一步提高，并将政策截止期限延长至2016年底。这一措施____', '["将拓宽小微企业融资渠道", "有利于减轻小微企业债务负担", "有助于小微企成长的根本之策", "有助于拓宽小微企业利润空间"]', 'D', '参考答案：D。本题考查经济生活，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '2014年4月2日，国务院提出将小微企业减半征收企业所得税优惠政策实施范围上限由年应纳税所得额6万元进一步提高，并将政策截止期限延长至2016年底。这一措施____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_6 AS CHAR), 'SINGLE_CHOICE', '日前，美国总统特朗普签署行政命令，暂时禁止七个伊斯兰国家的普通公民入境美国，对叙利亚公民无限期停发签证和停止难民庇护申请处理。这一入境限制令颁布后，遭到美国国内和国际的批评和抗议。没过多久，美国联邦法官对这一禁令进行裁决，最终判定该禁令违背宪法，决定暂时撤销总统行政令。判决即刻生效，美国边检已对滞留者放行。但白宫发表声明说，将申请紧急对这一裁决进行延缓，并保护总统的行政命令。这说明，在美国____', '["立法机关与司法机关之间相互制衡", "政治运行贯彻“三权分立”的原则", "总统享有立法倡议权，有权否决同会立法", "两党在移民问题上的政策和主张有本质上的差别"]', 'B', '参考答案：B。本题考查政治制度与法治，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '日前，美国总统特朗普签署行政命令，暂时禁止七个伊斯兰国家的普通公民入境美国，对叙利亚公民无限期停发签证和停止难民庇护申请处理。这一入境限制令颁布后，遭到美国国内和国际的批评和抗议。没过多久，美国联邦法官对这一禁令进行裁决，最终判定该禁令违背宪法，决定暂时撤销总统行政令。判决即刻生效，美国边检已对滞留者放行。但白宫发表声明说，将申请紧急对这一裁决进行延缓，并保护总统的行政命令。这说明，在美国____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_8 AS CHAR), 'SINGLE_CHOICE', '抽象的可能性是指____', '["现实的可能性", "非现实的可能性", "抽象思维中的可能性", "坏的可能性"]', 'B', '参考答案：B。本题考查政治综合，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '抽象的可能性是指____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_1 AS CHAR), 'SINGLE_CHOICE', '石头和电脑是两种不同的物质存在，石头是自然界演化而来的，在人出现之前就已经存在了，而自然界本来没有电脑，它是人制造出来的。大自然可以演化出一座珠穆朗玛峰，但无论怎样也不可能演化出一台电脑。这说明人的意识____', '["能够能动地认识世界", "能够能动地改造世界", "能够调节人的生理活动", "能够直接变成为物质"]', 'B', '参考答案：B。本题考查唯物论与认识论，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '石头和电脑是两种不同的物质存在，石头是自然界演化而来的，在人出现之前就已经存在了，而自然界本来没有电脑，它是人制造出来的。大自然可以演化出一座珠穆朗玛峰，但无论怎样也不可能演化出一台电脑。这说明人的意识____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_2 AS CHAR), 'SINGLE_CHOICE', '英法两国地理上同在欧洲，历史上同样经历了资产阶级革命，现在同为资本主义国家。英国资产阶级革命不彻底，保留了君主制；法国资产阶级革命彻底地摧毁了封建专制制度，建立了共和国。英法两国政体的“异同”表明____\n①矛盾的普遍性中包含着特殊性\n②利用矛盾的特殊性可以区分事物\n③矛盾的普遍性寓于特殊性之中\n④矛盾的普遍性和特殊性对立统一', '["①③", "①④", "②③", "②④"]', 'D', '参考答案：D。本题考查辩证法，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '英法两国地理上同在欧洲，历史上同样经历了资产阶级革命，现在同为资本主义国家。英国资产阶级革命不彻底，保留了君主制；法国资产阶级革命彻底地摧毁了封建专制制度，建立了共和国。英法两国政体的“异同”表明____\n①矛盾的普遍性中包含着特殊性\n②利用矛盾的特殊性可以区分事物\n③矛盾的普遍性寓于特殊性之中\n④矛盾的普遍性和特殊性对立统一');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_3 AS CHAR), 'SINGLE_CHOICE', '2015年2月我国某手机价值用人民币表示为1342元，当时美元对人民币的汇率为1美元=6.1元人民币。如果2015年11月生产该手机的社会劳动生产率提高了30%，物价上涨了30%，假设此时人民币对美元升值了5%，在其他条件不变的情况下，则2015年11月该手机的价格以美元表示为____', '["211美元", "191美元", "200.5美元", "231美元"]', 'D', '参考答案：D。本题考查社会历史观与价值观，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '2015年2月我国某手机价值用人民币表示为1342元，当时美元对人民币的汇率为1美元=6.1元人民币。如果2015年11月生产该手机的社会劳动生产率提高了30%，物价上涨了30%，假设此时人民币对美元升值了5%，在其他条件不变的情况下，则2015年11月该手机的价格以美元表示为____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_4 AS CHAR), 'SINGLE_CHOICE', '1000 年前，世界上第一张纸币“交子”诞生在中国，推动人类货币史前进了一大步；1000年后，中国人民银行有望成为全球首个推出数字货币的央行，再次引领货币金融领域的新变革。通俗地来说，央行数字货币就是法币的数字化，“只要你我手机上都有 DC/EP 的数字钱包，连网络都不需要，只要手机有电，两个手机碰一碰，就能把一个人数字钱包里的数字货币，转给另一个人。”双离线交易、碰一碰支付、可不设立银行账户等央行数字货币的创新功能让许多人眼前一亮。下列对我国将使用“法定数字货币”的推论正确的是____\n①法定数字货币采用新技术，使用后能增加货币职能\n②“点对点”支付节省中间环节，提高贸易的便捷性\n③数字货币的使用让消费信息更加透明，增进企业合作\n④我国优先将数字货币用于国际贸易结算，有利于推进人民币国际化', '["①③", "①④", "②③", "②④"]', 'D', '参考答案：D。本题考查文化传承与创新，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '1000 年前，世界上第一张纸币“交子”诞生在中国，推动人类货币史前进了一大步；1000年后，中国人民银行有望成为全球首个推出数字货币的央行，再次引领货币金融领域的新变革。通俗地来说，央行数字货币就是法币的数字化，“只要你我手机上都有 DC/EP 的数字钱包，连网络都不需要，只要手机有电，两个手机碰一碰，就能把一个人数字钱包里的数字货币，转给另一个人。”双离线交易、碰一碰支付、可不设立银行账户等央行数字货币的创新功能让许多人眼前一亮。下列对我国将使用“法定数字货币”的推论正确的是____\n①法定数字货币采用新技术，使用后能增加货币职能\n②“点对点”支付节省中间环节，提高贸易的便捷性\n③数字货币的使用让消费信息更加透明，增进企业合作\n④我国优先将数字货币用于国际贸易结算，有利于推进人民币国际化');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_5 AS CHAR), 'SINGLE_CHOICE', '“别人冷时我正热，市场缺时我正有。”市场切忌“赶”，“逢快莫赶，逢滞莫丢”这个规律启示我们____', '["应努力提高劳动生产率", "应诚实守信，合法经营", "应生产科技含量高的优质产品", "必须遵循价值规律，适应市场供求关系的变化"]', 'D', '参考答案：D。本题考查经济生活，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '“别人冷时我正热，市场缺时我正有。”市场切忌“赶”，“逢快莫赶，逢滞莫丢”这个规律启示我们____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_6 AS CHAR), 'SINGLE_CHOICE', '小明同学在某街道发现“××街道办事处”和“××社区居委会”两个单位牌子，对这两者关系不太了解，下列解释正确的是____\n①居委会和街道办事处是隶属关系\n②街道办事处指导居委会的工作\n③二者均由区人大选举产生，共同履行管理和服务职能\n④街道办事处是政府的派出机关，居委会是基层群众性自治组织', '["①③", "①④", "②③", "②④"]', 'D', '参考答案：D。本题考查政治制度与法治，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '小明同学在某街道发现“××街道办事处”和“××社区居委会”两个单位牌子，对这两者关系不太了解，下列解释正确的是____\n①居委会和街道办事处是隶属关系\n②街道办事处指导居委会的工作\n③二者均由区人大选举产生，共同履行管理和服务职能\n④街道办事处是政府的派出机关，居委会是基层群众性自治组织');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_8 AS CHAR), 'SINGLE_CHOICE', '2012年8月18日，来华访问的美国副总统拜登一行到北京鼓楼吃炸酱面。一行5人共花费79元，拜登掏出100元人民币结账。将结余的21元当小费送给了服务员。材料中的____', '["79元执行的是价值尺度职能", "21元为劳务报酬", "100元是一般等价物", "结算方式为现金结算，消费类型为钱货两清的消费"]', 'D', '参考答案：D。本题考查政治综合，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '2012年8月18日，来华访问的美国副总统拜登一行到北京鼓楼吃炸酱面。一行5人共花费79元，拜登掏出100元人民币结账。将结余的21元当小费送给了服务员。材料中的____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_1 AS CHAR), 'SINGLE_CHOICE', '《北京市野生动物保护管理条例》于 2020 年 6 月 1 日起实施。《条例》完善了野生动物保护管理体系，坚持了“尊重自然、顺应自然、保护自然”的理念，遵循了“全面保护、严格监管、保障安全”的原则，有利于树立全社会保护野生动物的意识，促进人与自然和谐共生。该《条例》蕴含的思想____\n①尊重了自然界和人类社会的物质性，改造了客观世界\n②发挥了上层建筑的调节作用，保证人民群众生命安全\n③适应了人们实践的需要，有助于人们实践活动的发展\n④反映了社会存在，引导人们作出正确的价值判断与选择', '["①②", "①④", "②③", "③④"]', 'D', '参考答案：D。本题考查唯物论与认识论，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '《北京市野生动物保护管理条例》于 2020 年 6 月 1 日起实施。《条例》完善了野生动物保护管理体系，坚持了“尊重自然、顺应自然、保护自然”的理念，遵循了“全面保护、严格监管、保障安全”的原则，有利于树立全社会保护野生动物的意识，促进人与自然和谐共生。该《条例》蕴含的思想____\n①尊重了自然界和人类社会的物质性，改造了客观世界\n②发挥了上层建筑的调节作用，保证人民群众生命安全\n③适应了人们实践的需要，有助于人们实践活动的发展\n④反映了社会存在，引导人们作出正确的价值判断与选择');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_2 AS CHAR), 'SINGLE_CHOICE', '党的十八届三中全会《关于全面深化改革若干重大问题的决定》突破了原有规定，指出，“在加强监管前提下，我国一些具备条件的民间资本可以依法成立中小型银行等金融机构”。这是由于____\n①应该变我国商业银行以国有控股银行为主体的局面\n②各种所有制经济在我国金融业的市场地位是平等的\n③金融体系的完善要发挥国家对资源配置的决定作用\n④发展中小型银行等能促进我国金融业提高服务水平', '["②③", "②④", "③④", "①②"]', 'B', '参考答案：B。本题考查辩证法，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '党的十八届三中全会《关于全面深化改革若干重大问题的决定》突破了原有规定，指出，“在加强监管前提下，我国一些具备条件的民间资本可以依法成立中小型银行等金融机构”。这是由于____\n①应该变我国商业银行以国有控股银行为主体的局面\n②各种所有制经济在我国金融业的市场地位是平等的\n③金融体系的完善要发挥国家对资源配置的决定作用\n④发展中小型银行等能促进我国金融业提高服务水平');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_3 AS CHAR), 'SINGLE_CHOICE', '面对通货膨胀和金价上涨，国内黄金产品销量大增。在纸币贬值的情况下，人们选择黄金投资是因为____\n①纸币作为价值符号，在贬值时所代表的实际价值会缩水\n②纸币的发行量少于流通中所需要的货币量会产生贬值\n③把黄金作为社会财富的代表贮藏起来可以保值、增值\n④黄金作为商品其价值是固定的，人们投资黄金风险小', '["①③", "①④", "③④", "②③"]', 'A', '参考答案：A。本题考查社会历史观与价值观，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '面对通货膨胀和金价上涨，国内黄金产品销量大增。在纸币贬值的情况下，人们选择黄金投资是因为____\n①纸币作为价值符号，在贬值时所代表的实际价值会缩水\n②纸币的发行量少于流通中所需要的货币量会产生贬值\n③把黄金作为社会财富的代表贮藏起来可以保值、增值\n④黄金作为商品其价值是固定的，人们投资黄金风险小');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_4 AS CHAR), 'SINGLE_CHOICE', '为了民族复兴，再铸中华文化的辉煌，无数仁人志士上下求索，寻找救国良方，进行了可歌可泣的斗争，进行了各式各样的尝试。19 世纪末 20 世纪初，各种各样的文化思潮进入中国，都不能解决中国文化走向何处的问题，无法使中华文化走向复兴之路。那么，中华文化由衰微走向重振的转折点是____', '["辛亥革命推翻清王朝", "马克思主义传入中国", "中华人民共和国成立", "十一届三中全会之后"]', 'B', '参考答案：B。本题考查文化传承与创新，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '为了民族复兴，再铸中华文化的辉煌，无数仁人志士上下求索，寻找救国良方，进行了可歌可泣的斗争，进行了各式各样的尝试。19 世纪末 20 世纪初，各种各样的文化思潮进入中国，都不能解决中国文化走向何处的问题，无法使中华文化走向复兴之路。那么，中华文化由衰微走向重振的转折点是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_5 AS CHAR), 'SINGLE_CHOICE', '温家宝总理说，要千方百计促进就业。充分发挥服务业.中小企业、非公有制经济在吸纳就业中的作用，以创业带动就业。对就业观的正确理解____', '["等待理想单位就业", "就业要一次成功", "先就业后择业或自主创业", "追求体面的、报酬高的职业"]', 'C', '参考答案：C。本题考查经济生活，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '温家宝总理说，要千方百计促进就业。充分发挥服务业.中小企业、非公有制经济在吸纳就业中的作用，以创业带动就业。对就业观的正确理解____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_6 AS CHAR), 'SINGLE_CHOICE', '《北京市物业管理条例》于 2020 年 5 月 1 日起实施。“飞线”给电动车充电、私家车主占用消防通道等造成安全隐患的行为将被规范，并受到相应的处罚。下列关于该“条例”的制定过程分析正确的是____\n①人大代表听取市民对“管理条例”的建议----人大代表自觉接受群众监督\n②市政协履行职能，提出 240 条意见建议----协商民主发挥作用，彰显优势\n③该条例经市人大常委会审议并表决通过----市人大常委会民主科学立法\n④行政执法部门按条例对违规行为进行处罚——政府履行职能，依法行政', '["①②", "①④", "②③", "③④"]', 'C', '参考答案：C。本题考查政治制度与法治，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '《北京市物业管理条例》于 2020 年 5 月 1 日起实施。“飞线”给电动车充电、私家车主占用消防通道等造成安全隐患的行为将被规范，并受到相应的处罚。下列关于该“条例”的制定过程分析正确的是____\n①人大代表听取市民对“管理条例”的建议----人大代表自觉接受群众监督\n②市政协履行职能，提出 240 条意见建议----协商民主发挥作用，彰显优势\n③该条例经市人大常委会审议并表决通过----市人大常委会民主科学立法\n④行政执法部门按条例对违规行为进行处罚——政府履行职能，依法行政');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_8 AS CHAR), 'SINGLE_CHOICE', '2015年2月，中国国家发改委裁定美国高通公司违反我国《反垄断法》，处以9.75亿美元的罚金，并责令整改。发改委此举____', '["体现了市场竞争规则的要求", "符合统一的市场准入制度", "是用经济手段规范市场秩序", "有效克服了市场调节的弊端"]', 'A', '参考答案：A。本题考查政治综合，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '2015年2月，中国国家发改委裁定美国高通公司违反我国《反垄断法》，处以9.75亿美元的罚金，并责令整改。发改委此举____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_1 AS CHAR), 'SINGLE_CHOICE', '如果我们把不同的商品放在一起，会发现这些商品的价格各不相同，有的高，有的低；如果我们把视线放在同一种商品上，也会发现这种商品的价格不是固定不变的，它有时高，有时低。对这两种情况出现的价格的“高、低”的正确认识是____', '["本质是一样的，都是由于生产商品的社会必要劳动时间不同造成的", "本质是一样的，都是由市场供求关系变化引起的", "本质不同，前者是由供求关系的变化引起的，后者是由于价值量不同造成的", "本质不同，前者是由于价值量不同造成的，后者是由于供求关系变化引起的"]', 'D', '参考答案：D。本题考查唯物论与认识论，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '如果我们把不同的商品放在一起，会发现这些商品的价格各不相同，有的高，有的低；如果我们把视线放在同一种商品上，也会发现这种商品的价格不是固定不变的，它有时高，有时低。对这两种情况出现的价格的“高、低”的正确认识是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_2 AS CHAR), 'SINGLE_CHOICE', '新时代铸就民族新发展。文山壮族苗族自治州开展旅游扶贫，依靠绿水青山打造旅游循环经济，创造美好生活；在安徽，赛涧回族乡实行产业扶贫，建设服饰品牌，激发少数民族贫困群众内生动力；在青海，土族县易地扶贫搬迁，走出大山，奔向小康。这表明，我国____', '["走中国特色社会主义道路以实现同步富裕", "铸牢中华民族共同体意识促进民族团结进步", "切实保障少数民族地区拥有更多的自治权", "基本消除了不同民族的经济发展差别"]', 'B', '参考答案：B。本题考查辩证法，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '新时代铸就民族新发展。文山壮族苗族自治州开展旅游扶贫，依靠绿水青山打造旅游循环经济，创造美好生活；在安徽，赛涧回族乡实行产业扶贫，建设服饰品牌，激发少数民族贫困群众内生动力；在青海，土族县易地扶贫搬迁，走出大山，奔向小康。这表明，我国____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_3 AS CHAR), 'SINGLE_CHOICE', '据报道，2012年9月上海私车额度最低中标价（注：车牌价格）65700元，比上月上涨3600元，创出上海自2000年举行私车额度拍卖以来的最高纪录。上海私车额度价格大幅上涨的原因可能有____\n	①部分市民因“十一黄金周”外出旅游急需上牌      ②汽油价格不断上升\n③市场炒作的推动                              ④车牌的价值量增加', '["①②", "①③", "②③", "③④"]', 'B', '参考答案：B。本题考查社会历史观与价值观，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '据报道，2012年9月上海私车额度最低中标价（注：车牌价格）65700元，比上月上涨3600元，创出上海自2000年举行私车额度拍卖以来的最高纪录。上海私车额度价格大幅上涨的原因可能有____\n	①部分市民因“十一黄金周”外出旅游急需上牌      ②汽油价格不断上升\n③市场炒作的推动                              ④车牌的价值量增加');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_4 AS CHAR), 'SINGLE_CHOICE', '2017年，央视《中国诗词大会》节目，以“赏中华诗词，寻文化基因，品生活之美”为主旨。通过对诗词知识的比拼及赏析，带动全民重温那些曾经学过的古诗词，感受诗词之趣此节目不仅摘得收视率桂冠，也在全国掀起一股学习背诵古诗词的热潮，其原因存于____\n①优秀文化生生不息，源远流长    ②中华韵味民族认同，雅俗共赏\n③声像合一新颖创新，引人人胜    ④吟诗赏识全民动员，古诗新作', '["①②", "①③", "②③", "②④"]', 'A', '参考答案：A。本题考查文化传承与创新，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '2017年，央视《中国诗词大会》节目，以“赏中华诗词，寻文化基因，品生活之美”为主旨。通过对诗词知识的比拼及赏析，带动全民重温那些曾经学过的古诗词，感受诗词之趣此节目不仅摘得收视率桂冠，也在全国掀起一股学习背诵古诗词的热潮，其原因存于____\n①优秀文化生生不息，源远流长    ②中华韵味民族认同，雅俗共赏\n③声像合一新颖创新，引人人胜    ④吟诗赏识全民动员，古诗新作');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_5 AS CHAR), 'SINGLE_CHOICE', '“河狸族”是指当下与河狸有共同特点的网购人群，他们擅长用优惠券进行网购，主张“无优惠，不网购”的消费理念。“河狸族”践行的消费原则主要是____', '["量入为出，超前消费", "避免盲从，理性消费", "保护环境，绿色消费", "勤俭节约，滞后消费"]', 'B', '参考答案：B。本题考查经济生活，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '“河狸族”是指当下与河狸有共同特点的网购人群，他们擅长用优惠券进行网购，主张“无优惠，不网购”的消费理念。“河狸族”践行的消费原则主要是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_6 AS CHAR), 'SINGLE_CHOICE', '在世界格局走向多极化，国际形势复杂多变的背景下，我国要加强人民军队建设。加强人民军队建设必须：____\n①坚持党对军队的绝对领导 ②坚持依法治军、从严治军\n③坚持科技强军战略 ④坚持全心全意为人民服务的宗旨', '["①②③", "②③④", "①②", "①②③④"]', 'D', '参考答案：D。本题考查政治制度与法治，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '在世界格局走向多极化，国际形势复杂多变的背景下，我国要加强人民军队建设。加强人民军队建设必须：____\n①坚持党对军队的绝对领导 ②坚持依法治军、从严治军\n③坚持科技强军战略 ④坚持全心全意为人民服务的宗旨');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_8 AS CHAR), 'SINGLE_CHOICE', '截至2010年3月，我国外汇储备余额为2.42万亿元。外汇是____', '["我国居民或法人持有的美元", "两种货币之间的兑换关系", "用于国际间结算的支付凭证", "对外开放程度的标志"]', 'B', '参考答案：B。本题考查政治综合，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '截至2010年3月，我国外汇储备余额为2.42万亿元。外汇是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_1 AS CHAR), 'SINGLE_CHOICE', '2015年3月，我国工业生产者出厂价格指数（PPI）同比下降4.6%，一年同比持续呈下降趋势。对这一趋势可能带来的影响认识正确的是____\n①企业生产规模扩大            ②相关企业改变生产要素的投入，以降低生产成本\n③社会总体消费水平下降        ④劳动者收入提高', '["①③", "②③", "②④", "①④"]', 'B', '参考答案：B。本题考查唯物论与认识论，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '2015年3月，我国工业生产者出厂价格指数（PPI）同比下降4.6%，一年同比持续呈下降趋势。对这一趋势可能带来的影响认识正确的是____\n①企业生产规模扩大            ②相关企业改变生产要素的投入，以降低生产成本\n③社会总体消费水平下降        ④劳动者收入提高');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_2 AS CHAR), 'SINGLE_CHOICE', '近日，“囤药清单”话题在网络上引起广泛讨论，清单中的退热药对乙酰氨基酚更是被推上“神坛”，引发抢购热潮。对此，有关专家提醒：“用药需谨慎，吃药须对症。”药品的使用是把双刃剑，药品的正确使用可以加速恢复健康，使用不当或过量则可能造成药物中毒。____\n①要积累量变促成质变\n②做事要遵循适度原则\n③做事要突出重点难点\n④要具体问题具体分析', '["①②", "①③", "②④", "③④"]', 'C', '参考答案：C。本题考查辩证法，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '近日，“囤药清单”话题在网络上引起广泛讨论，清单中的退热药对乙酰氨基酚更是被推上“神坛”，引发抢购热潮。对此，有关专家提醒：“用药需谨慎，吃药须对症。”药品的使用是把双刃剑，药品的正确使用可以加速恢复健康，使用不当或过量则可能造成药物中毒。____\n①要积累量变促成质变\n②做事要遵循适度原则\n③做事要突出重点难点\n④要具体问题具体分析');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_3 AS CHAR), 'SINGLE_CHOICE', '假定2010年某商品价值用人民币表示为1596元，人民币汇率为1美元=7元人民币。如果2012年生产该商品的行业劳动生产率提高20%，且人民币对美元升值5%。若其他条件不变，该商品以美元标价应为____', '["200美元", "199.5美元", "192美元", "180.15美元"]', 'B', '参考答案：B。本题考查社会历史观与价值观，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '假定2010年某商品价值用人民币表示为1596元，人民币汇率为1美元=7元人民币。如果2012年生产该商品的行业劳动生产率提高20%，且人民币对美元升值5%。若其他条件不变，该商品以美元标价应为____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_4 AS CHAR), 'SINGLE_CHOICE', '市场调节和国家宏观调控都是现代市场经济的重要组成部分。以下是国家运用经济手段进行宏观调控的是____\n①9月5日，中国银行总行中小企业部研究创新金融服务和破解中小企业融资难问题\n②2014年3月，国务院出台了“关于进一步优化企业兼并重组市场环境的意见”\n③8月15日，国务院出台了《不动产登记暂行条例》\n④日前，国务院印发《社会信用体系建设规划纲要（2014—2020年）》', '["①④", "①②", "③④", "②④"]', 'D', '参考答案：D。本题考查文化传承与创新，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '市场调节和国家宏观调控都是现代市场经济的重要组成部分。以下是国家运用经济手段进行宏观调控的是____\n①9月5日，中国银行总行中小企业部研究创新金融服务和破解中小企业融资难问题\n②2014年3月，国务院出台了“关于进一步优化企业兼并重组市场环境的意见”\n③8月15日，国务院出台了《不动产登记暂行条例》\n④日前，国务院印发《社会信用体系建设规划纲要（2014—2020年）》');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_5 AS CHAR), 'SINGLE_CHOICE', '定于2015年“五一”结婚的王某到超市购买了结婚用品，到婚纱影楼租了婚纱和礼车，并用按揭付款的方式购买了住房。下列正确反映王某消费过程的消费类型是____', '["钱货两清消费、租赁消费、贷款消费", "生活必需品消费、高档耐用品消费、贷款消费", "钱货两清消费、生存资料消费、租赁消费", "生存资料消费、发展资料消费、享受资料消费"]', 'A', '参考答案：A。本题考查经济生活，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '定于2015年“五一”结婚的王某到超市购买了结婚用品，到婚纱影楼租了婚纱和礼车，并用按揭付款的方式购买了住房。下列正确反映王某消费过程的消费类型是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_6 AS CHAR), 'SINGLE_CHOICE', '“知屋漏者在宇下，知政失者在荒野”，如果从政府权力监督的角度看，这主要是强调____', '["国家权力机关对政府的监督", "民政协对政府的监督", "会与公民对政府的监督", "法机关对政府的监督"]', 'C', '参考答案：C。本题考查政治制度与法治，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '“知屋漏者在宇下，知政失者在荒野”，如果从政府权力监督的角度看，这主要是强调____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_8 AS CHAR), 'SINGLE_CHOICE', '资本主义道路在中国走不通的最根本原因是____', '["帝国主义不容许", "封建主义不容许", "无产阶级不容许", "民族资产阶级的妥协性、软弱性"]', 'D', '参考答案：D。本题考查政治综合，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '资本主义道路在中国走不通的最根本原因是____');
INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at, updated_at) SELECT @subject_politics, CAST(@kp_politics_1 AS CHAR), 'SINGLE_CHOICE', '“好雨知时节，当春乃发生”，说的是难得的春季降水，这些自然界降水、光照、大气等能被人类生产和生活所利用的自然物质和能量统称为气候资源。随着人们对气候规律认识的深化与生态文明实践进步，气候资源的概念逐步走入大众的视野，被更多人了解。这有利于我们____', '["更好开发利用和保护气候资源，改造自然规律，造福人类", "在生产生活中落实绿色发展理念，实现人与自然和谐相处", "发挥主观能动性，改变我国气候资源分布不均的现状", "深化我们对气候的认识，使之完全超越历史条件"]', 'B', '参考答案：B。本题考查唯物论与认识论，需要把材料信息与教材原理对应，判断选项表述是否准确。', 3, 'smart_learning.sql精选-政治', @admin_id, NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM question WHERE subject_id = @subject_politics AND source = 'smart_learning.sql精选-政治' AND content = '“好雨知时节，当春乃发生”，说的是难得的春季降水，这些自然界降水、光照、大气等能被人类生产和生活所利用的自然物质和能量统称为气候资源。随着人们对气候规律认识的深化与生态文明实践进步，气候资源的概念逐步走入大众的视野，被更多人了解。这有利于我们____');
